package fr.ailegalcase.analysis;

public final class LegalDomainPromptBuilder {

    private static final String FAMILLE_INSTRUCTION = """

            ========== RÈGLE CRITIQUE DE CLASSIFICATION — À APPLIQUER EN PREMIER ==========
            Identifier le MÉCANISME FACTUEL (pièce signée / décision notifiée),
            JAMAIS la qualification demandée dans les arguments d'une partie.

            Exemples critiques :
            - Contrat de mariage signé (séparation de biens, participation aux acquêts) +
              arguments de la partie pour requalifier en communauté légale de fait →
              regime_matrimonial reste SEPARATION_BIENS (ou PARTICIPATION_ACQUETS) tant
              que le juge n'a pas requalifié ; la convention existe factuellement.
            - Mode de garde actuel acté dans une ordonnance provisoire vs demande de
              modification → mode_garde_detaille reflète l'ORDONNANCE EN COURS, pas la
              demande en cours d'instruction.
            - Convention de divorce signée mais non homologuée → elle sert d'indice
              sur le régime choisi mais la situation procédurale peut rester incertaine.
            ================================================================================

            Pour ce dossier de droit de la famille, inclure également dans le JSON les champs suivants :
            "pension_alimentaire_data" : objet avec les champs :
              "revenus_net_mensuel_debiteur" : revenu net mensuel du parent débiteur en euros, null si non détectable.
              "revenus_net_mensuel_creancier" : revenu net mensuel du parent créancier en euros, null si non détectable.
              "nb_enfants" : nombre d'enfants concernés par la pension, null si non détectable.
              "mode_garde" : mode de garde binaire (pour le calcul de pension), l'une de ces valeurs exactes : "EXCLUSIVE", "ALTERNEE", null si non détectable.
              "mode_garde_detaille" : mode de garde précis pour le calendrier F-FA-06, l'une de ces valeurs exactes (null si non déterminable avec certitude) : "ALTERNEE_FR" (résidence alternée 1 semaine sur 2 en France), "DVH_CLASSIQUE_FR" (droit de visite et hébergement classique 1 week-end sur 2 en France), "DVH_ELARGI_FR" (DVH élargi avec mercredi après-midi en France), "ALTERNEE_BE" (hébergement égalitaire en Belgique), "SECONDAIRE_BE" (hébergement secondaire classique en Belgique), "SECONDAIRE_ELARGI_BE" (hébergement secondaire élargi en Belgique). Si l'information ne permet pas de choisir parmi ces 6 valeurs, laisser null — le champ "mode_garde" binaire suffit pour la pension.
              "pays_applicable" : pays du barème applicable, l'une de ces valeurs exactes : "FRANCE", "BELGIQUE", null si non détectable.
            "prestation_compensatoire_data" : objet avec les champs :
              "revenus_net_mensuel_epoux_a" : revenu net mensuel de l'époux A en euros, null si non détectable.
              "revenus_net_mensuel_epoux_b" : revenu net mensuel de l'époux B en euros, null si non détectable.
              "duree_mariage_annees" : durée du mariage en années (entier), null si non détectable.
              "nb_enfants_charge" : nombre d'enfants à charge communs, null si non détectable.
              "pays_applicable" : pays applicable, l'une de ces valeurs exactes : "FRANCE", "BELGIQUE", null si non détectable.
            "liquidation_communaute_data" : objet avec les champs :
              "regime_matrimonial" : régime matrimonial détecté, l'une de ces valeurs exactes : "COMMUNAUTE_LEGALE", "SEPARATION_BIENS", "PARTICIPATION_ACQUETS", null si non détectable.
              "actif_commun" : tableau d'objets {libelle: string, valeur_estimee: number|null} listant les biens communs détectés dans les documents.
              "biens_propres_epoux_a" : tableau d'objets {libelle: string, valeur_estimee: number|null} listant les biens propres de l'époux A.
              "biens_propres_epoux_b" : tableau d'objets {libelle: string, valeur_estimee: number|null} listant les biens propres de l'époux B.
              "passif_commun" : tableau d'objets {libelle: string, montant: number|null} listant les dettes communes détectées.
            "divorce_consentement_validity_detection" (F-152) : objet avec une clé par critère de validité du divorce par consentement mutuel (art. 229 Code civil). Inclure UNIQUEMENT les clés suivantes (7 codes exacts) quand l'indice textuel est présent ; omettre complètement les clés dont l'information ne peut être établie. Chaque valeur : {"reponse": "OUI" | "NON" | "INCONNU", "justification": phrase courte citant l'indice textuel du dossier, max 500 car.}. Codes :
              "DC_MAJORITE" : les deux époux sont majeurs. "OUI" si leurs dates de naissance montrent la majorité à la date de signature, "NON" si un époux est mineur, "INCONNU" si les âges ne sont pas détectables.
              "DC_CONSENTEMENT_LIBRE" : absence de vice du consentement (pression, dol, violences conjugales récentes non purgées). "OUI" par défaut si aucun indice de vice ; "NON" si violences conjugales en cours, pression documentée, trouble majeur du consentement ; "INCONNU" si la question n'est pas abordée.
              "DC_CONVENTION_EQUITABLE" : convention qui ne lèse manifestement aucun époux (liquidation équilibrée, pension et prestation proportionnées). "OUI" si aucun déséquilibre notable ; "NON" si un époux renonce à sa part sans contrepartie apparente, ou si l'écart de revenus crée une iniquité flagrante non compensée ; "INCONNU" si la convention n'est pas détaillée.
              "DC_ENFANT_MINEUR_ENTENDU" : si au moins un enfant mineur ≥ âge de discernement (environ 10-12 ans), il a été informé de son droit à être entendu (art. 388-1 Cciv). "OUI" si une mention explicite figure dans les pièces ; "NON" si le formulaire obligatoire manque alors que l'enfant a l'âge requis ; "INCONNU" s'il n'y a pas d'enfant mineur OU si l'information est absente.
              "DC_DELAI_REFLEXION_15J" : délai de 15 jours calendaires entre réception de la convention par l'époux et sa signature (art. 229-4 Cciv). "OUI" si les deux dates figurent et l'intervalle ≥ 15 jours ; "NON" si < 15 jours ; "INCONNU" si au moins une date manque.
              "DC_NOTAIRE_DEPOT" : convention déposée chez un notaire pour acquisition de la date certaine (art. 229-1 Cciv). "OUI" si un acte de dépôt notarial est documenté ; "NON" si explicitement non fait ou si le mode de divorce est autre (contentieux) ; "INCONNU" si la procédure n'en est pas encore là.
              "DC_INDEPENDANCE_AVOCATS" : chaque époux a son propre avocat (pas d'avocat unique). "OUI" si deux avocats distincts sont identifiés ; "NON" si un seul avocat signe pour les deux (cas de nullité de droit) ; "INCONNU" si les avocats ne sont pas identifiables dans les pièces.
            "famille_extracted_data" : objet contenant les flags de détection Famille FR/BE pour le panneau décisionnel F-IA-04. Tous les flags sont booléens avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces.
            F-200 — 30 flags décisionnels niveau 3 (FR), FRANCE UNIQUEMENT. Pour un dossier famille BELGIQUE, TOUS ces 30 flags FR DOIVENT rester false (les régimes BE équivalents sont gérés par les 5 flags BE listés plus bas — F-202). Permettent à F-IA-04 de basculer 30 outils Famille FR ALWAYS_ON → CONTEXTUAL (réduction attendue −91 % du bruit panel).
              "divorce_consentement_mutuel_envisage" : booléen — true uniquement si les pièces évoquent un divorce par consentement mutuel notarié (art. 229-1 à 229-3 Cciv) avec indice factuel (convention de divorce signée ou en cours, mention "229-1", "CM", "convention divorce", projet d'acte notarié, deux avocats distincts identifiés). False par défaut. Pertinent pour F-FA-07.
              "divorce_alteration_lien_envisage" : booléen — true uniquement si les pièces évoquent un divorce pour altération définitive du lien conjugal (art. 237-238 Cciv) avec indice factuel (séparation effective ≥ 1 an documentée, attestation séparation, justificatifs domiciles distincts, mention "altération du lien", "237", "238"). False par défaut. Pertinent pour F-FA-08.
              "divorce_faute_envisage" : booléen — true uniquement si les pièces évoquent un divorce pour faute (art. 242 Cciv) avec indice factuel (violences conjugales, adultère, abandon du domicile conjugal, manquement grave aux devoirs et obligations du mariage, mention "242", main courante, plainte, témoignages). False par défaut. Pertinent pour F-FA-09.
              "divorce_accepte_envisage" : booléen — true uniquement si les pièces évoquent un divorce accepté (art. 233-234 Cciv) avec indice factuel (PV d'acceptation du principe de la rupture signé, mention "233", "234", "acceptation principe rupture", procès-verbal d'acceptation devant le juge). False par défaut. Pertinent pour F-FA-10.
              "revision_post_divorce_envisagee" : booléen — true uniquement si les pièces évoquent une révision post-divorce d'une pension alimentaire ou prestation compensatoire (art. 276-3 Cciv pour PC, art. 373-2-2 Cciv pour PA enfant) avec indice factuel (changement de situation documenté — perte d'emploi, naissance, retraite, etc., demande de révision rédigée, mention "276-3", "révision pension", "modification ordonnance"). False par défaut. Pertinent pour F-FA-13.
              "ordonnance_protection_envisagee" : booléen — true uniquement si les pièces évoquent une demande d'ordonnance de protection (art. 515-9 à 515-13 Cciv) avec indice factuel (violences conjugales documentées, certificat médical de coups, dépôt de plainte, requête JAF, mention "515-9", "BAR", "TGD", "ordonnance protection", "main courante violences"). False par défaut. Pertinent pour F-FA-14. CAS GRAVE — toujours signaler dès le moindre indice factuel.
              "recompenses_envisagees" : booléen — true uniquement si le régime matrimonial détecté est COMMUNAUTE_LEGALE ou COMMUNAUTE_UNIVERSELLE et qu'une question de récompenses entre patrimoine commun et patrimoine propre est documentée (art. 1433+ Cciv) avec indice factuel (apports propres dans bien commun, dette commune payée par patrimoine propre, mention "récompenses", "1433"). False si régime SEPARATION_BIENS ou PARTICIPATION_ACQUETS (pas de récompenses possible). False par défaut. Pertinent pour F-FA-15.
              "regime_communaute_universelle_detecte" : booléen — true uniquement si le contrat de mariage détecté est en régime de communauté universelle (art. 1526-1527 al. 2 Cciv) avec indice factuel (acte notarié de contrat de mariage produit, mention "communauté universelle", "1526", "clause d'attribution intégrale au survivant", "clause de retranchement"). False par défaut (régime rare en France). Pertinent pour F-FA-16.
              "partage_judiciaire_envisage" : booléen — true uniquement si les pièces évoquent un partage judiciaire (art. 840 Cciv) avec indice factuel (PV de difficultés notarial, tentative amiable épuisée documentée, assignation en partage rédigée, désaccord coindivisaires, mention "840", "partage judiciaire", "PV difficultés"). False par défaut. Pertinent pour F-FA-17.
              "adoption_envisagee" : booléen — true uniquement si les pièces évoquent une procédure d'adoption (art. 343 à 370-3 Cciv) avec indice factuel (agrément délivré ou demandé, jugement d'adoption requis, OAA / pupille de l'État, adoption intra-familiale, mention "adoption", "agrément", "pupille"). False par défaut. Pertinent pour F-FA-18.
              "reconnaissance_paternelle_envisagee" : booléen — true uniquement si les pièces évoquent une reconnaissance de paternité (ou maternité) à effectuer ou contester (art. 316 Cciv) avec indice factuel (acte de reconnaissance produit, demande de reconnaissance, mention "316", "reconnaissance enfant"). False par défaut, et notamment false si la filiation est déjà établie sans question. Pertinent pour F-FA-18-reconnaissance-paternelle.
              "contestation_paternite_envisagee" : booléen — true uniquement si les pièces évoquent une contestation de paternité (ou maternité) (art. 332-335 Cciv) avec indice factuel (demande de désaveu, expertise génétique, mention "332", "333", "334", "335", "contestation paternité", "désaveu"). False par défaut. Pertinent pour F-FA-18-contestation-paternite.
              "recherche_paternite_envisagee" : booléen — true uniquement si les pièces évoquent une recherche de paternité (action en) (art. 327 Cciv) avec indice factuel (demande d'expertise ADN, action contre père présumé, mention "327", "recherche paternité", "expertise ADN"). False par défaut. Pertinent pour F-FA-18-recherche-paternite.
              "possession_etat_envisagee" : booléen — true uniquement si les pièces évoquent un acte de notoriété fondé sur la possession d'état (art. 311-1, 317 Cciv) avec indice factuel (témoignages de notoire publique, fasciculus, tractatus, nomen, demande d'acte de notoriété au juge, mention "311-1", "317", "possession d'état"). False par défaut. Pertinent pour F-FA-18-possession-etat.
              "changement_residence_envisage" : booléen — true uniquement si les pièces évoquent un déménagement / changement de résidence d'un parent qui modifie l'exercice de l'autorité parentale (art. 373-2 Cciv) avec indice factuel (notification déménagement, mutation professionnelle, opposition de l'autre parent, requête JAF, mention "373-2", "déménagement", "mutation"). False par défaut. Pertinent pour F-FA-19-changement-residence.
              "desaccord_parental_detecte" : booléen — true uniquement si les pièces évoquent un désaccord persistant entre parents séparés sur un acte usuel ou non usuel relatif à l'enfant (art. 373-2-10 Cciv) avec indice factuel (correspondances en désaccord scolarité, religion, santé, sortie du territoire, mention "373-2-10", "désaccord parental", saisine JAF). False par défaut. Pertinent pour F-FA-19-desaccords-parentaux.
              "pacs_dissolution_envisagee" : booléen — true uniquement si les pièces évoquent une dissolution de PACS (art. 515-7 Cciv) avec indice factuel (déclaration conjointe, mariage entre partenaires, décès, mention "PACS", "dissolution PACS", "515-7"). False par défaut. Pertinent pour F-FA-20.
              "separation_corps_envisagee" : booléen — true uniquement si les pièces évoquent une séparation de corps (art. 296 à 308 Cciv) — non un divorce — avec indice factuel (assignation en séparation de corps, conversion en divorce envisagée, mention "296", "séparation de corps"). False par défaut (cas peu fréquent, ne pas confondre avec séparation de fait). Pertinent pour F-FA-21.
              "indivision_envisagee" : booléen — true uniquement si les pièces évoquent une indivision hors mariage / hors succession (art. 815 Cciv) avec indice factuel (achat indivis entre concubins / pacsés, sortie d'indivision demandée, mention "815", "indivision", "coindivisaire"). False si l'indivision est successorale (utiliser `indivision_successorale_envisagee`). False par défaut. Pertinent pour F-FA-22.
              "ordonnance_requete_envisagee" : booléen — true uniquement si les pièces évoquent une mesure urgente sur requête (art. 493 CPC) avec indice factuel (urgence documentée, mesure conservatoire demandée, séquestre, mention "493 CPC", "ordonnance sur requête"). False par défaut. Pertinent pour F-FA-23.
              "succession_envisagee" : booléen — true uniquement si les pièces comportent une succession ouverte ou imminente (décès attesté, acte de notoriété, déclaration de succession, mention "succession", "défunt", "décès", date d'ouverture). False par défaut. Pertinent comme pivot pour F-FA-24-devolution-legale + F-FA-24-partage-successoral + F-FA-24-indivision-successorale. CAS PIVOT — sans décès, aucun outil succession ne doit apparaître.
              "testament_envisage" : booléen — true uniquement si les pièces évoquent un testament (art. 967+ Cciv) avec indice factuel (testament olographe / authentique / mystique produit, mention "testament", forme testament détectée). False par défaut. Pertinent pour F-FA-24-testament-validite.
              "donation_envisagee" : booléen — true uniquement si les pièces évoquent une donation (art. 893+ Cciv) avec indice factuel (acte de donation produit, donation entre époux, donation-partage, mention "donation", "893", "1077"). False par défaut. Pertinent pour F-FA-24-donation.
              "reserve_hereditaire_envisagee" : booléen — true uniquement si les pièces évoquent une question de réserve héréditaire / quotité disponible (art. 912+ Cciv) avec indice factuel (legs excédant la quotité disponible, demande de réduction, mention "réserve héréditaire", "quotité disponible", "912", "913", "réduction"). False par défaut. Pertinent pour F-FA-24-reserve-heriditaire.
              "partage_successoral_envisage" : booléen — true uniquement si les pièces évoquent un partage de succession (art. 825+ Cciv) avec indice factuel (acte de partage notarié, mode de partage demandé, attribution préférentielle, mention "partage succession", "825", "832", "indemnité de réduction"). False par défaut. Pertinent pour F-FA-24-partage-successoral.
              "indivision_successorale_envisagee" : booléen — true uniquement si les pièces évoquent une indivision successorale (art. 815 Cciv post-décès) avec indice factuel (cohéritiers en indivision, mention "indivision successorale", "815 succession", convention d'indivision). False par défaut. Pertinent pour F-FA-24-indivision-successorale.
              "rapport_succession_envisage" : booléen — true uniquement si les pièces évoquent une question de rapport à succession (art. 843+ Cciv) avec indice factuel (donation antérieure à un héritier, demande de rapport, mention "843", "rapport succession", "rapport à la masse"). False par défaut. Pertinent pour F-FA-24-rapport-succession.
              "protection_majeur_envisagee" : booléen — true uniquement si les pièces évoquent une mesure de protection juridique d'un majeur (art. 425+ Cciv) avec indice factuel (sauvegarde de justice, curatelle, tutelle, habilitation familiale, mandat de protection future, certificat médical circonstancié, mention "425", "440", "tutelle", "curatelle"). False par défaut. Pertinent pour F-FA-25.
              "changement_etat_civil_envisage" : booléen — true uniquement si les pièces évoquent un changement d'état civil (changement de nom art. 61-1 Cciv, changement de prénom art. 60+, changement de mention de sexe à l'état civil) avec indice factuel (requête au TJ, demande au procureur, mention "61-1", "61-5", "changement nom", "changement prénom"). False par défaut. Pertinent pour F-FA-26.
              "pma_gpa_envisagee" : booléen — true uniquement si les pièces évoquent une procréation médicalement assistée (PMA) ou gestation pour autrui (GPA) (loi bioéthique 2/8/2021) avec indice factuel (consentement PMA produit, parcours AMP médicalement documenté, GPA à l'étranger, jugement de transcription, mention "PMA", "GPA", "couple femmes", "L.2141-2 CSP"). False par défaut. Pertinent pour F-FA-27. CAS SPÉCIFIQUE — 0 % d'utilité hors PMA/GPA, bruit majeur si maintenu ALWAYS_ON.
              "mediation_familiale_pre_saisine_pertinente" : booléen — true uniquement si les pièces évoquent une saisine envisagée du JAF pour modifier des modalités d'autorité parentale, contribution à l'entretien, résidence ou droit de visite (motif in-scope art. 373-2-10 al. 3 Cciv) ET qu'aucune tentative de médiation familiale n'est documentée ni aucune exception applicable (urgence, violences). Indice factuel : projet de requête JAF en autorité parentale / pension enfant / résidence / DVH, sans mention d'attestation de tentative de médiation. False par défaut. Pertinent pour l'outil `mediation-familiale-pre-saisine` (F-210). CAS PROCÉDURAL — l'irrecevabilité peut être soulevée d'office par le juge.
            F-202 — 5 flags décisionnels niveau 3 (BE), BELGIQUE UNIQUEMENT. Chaque flag est un booléen avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces. Pour un dossier famille FRANCE, TOUS ces 5 flags BE DOIVENT rester false (les régimes FR équivalents — divorce par consentement mutuel art. 229 Cciv, divorce contentieux 3 voies, PACS, donations FR — sont gérés par les flags F-200 ci-dessus).
              "divorce_dc_envisage" : booléen — true uniquement si le dossier évoque une procédure de divorce par consentement mutuel BE au sens du CJ art. 1287+ et de la Loi 27/04/2007 (mots-clés "consentement mutuel", "DC", "accord total entre époux", "convention préalable", "deux comparutions devant juge famille"). False par défaut. Pertinent pour les futurs outils `dc-be-conditions-recevabilite`, `dc-be-convention-prealable`, `dc-be-procedure-comparutions`.
              "divorce_ddi_envisage" : booléen — true uniquement si le dossier évoque une procédure de divorce pour désunion irrémédiable BE au sens du CC art. 229 § 1 ou § 3 et du CJ art. 1255 § 1 ou § 2 (mots-clés "désunion irrémédiable", "DDI", "séparation de N mois", "séparation 1 an", "faits constitutifs de mésentente persistante", "preuves de mésentente"). Couvre les 3 voies du DDI : séparation prouvée 6 mois consensuelle, séparation prouvée 1 an unilatérale, faits constitutifs sans délai. False par défaut. Pertinent pour `F-FA-11-desunion-irremediable-be` (existant) et futurs outils `ddi-be-separation-1an-unilaterale`, `ddi-be-faits-preuves`.
              "cohabitation_legale_be_detectee" : booléen — true uniquement si le dossier évoque la cohabitation légale BE au sens de la Loi 23/11/1998 et du CC art. 1475+ / 1476 (mots-clés "cohabitation légale", "déclaration commune devant l'officier d'état civil", "dissolution cohabitation légale", "déclaration unilatérale fin cohabitation"). Distinct du PACS français. False par défaut. Pertinent pour les futurs outils `cohabitation-legale-be-formation`, `cohabitation-legale-be-effets`, `cohabitation-legale-be-dissolution`.
              "pacte_successoral_envisage" : booléen — true uniquement si le dossier évoque un pacte successoral BE au sens du CC art. 1100/1+ (Loi 31/07/2017 réforme succession, en vigueur 01/09/2018) — pacte global ou ponctuel, renonciation héréditaire anticipée, accord patrimonial pluripartite. **Spécificité BE post-2018, aucun équivalent FR** (Cciv art. 1130 al. 2 interdit la renonciation à une succession non ouverte). False par défaut. Pertinent pour le futur outil `succession-be-pacte-successoral`.
              "kafala_recueil_detecte" : booléen — true uniquement si le dossier évoque la kafala (recueil légal en droit musulman) avec une question de reconnaissance ou d'effets en BE au sens du CDIP belge et du CC art. 343 al. 2 nouveau (qui exclut l'adoption-kafala mais admet le recueil légal via le DIP). **Spécificité BE — la France refuse l'adoption d'enfant kafala (Cciv art. 370-3), la Belgique reconnaît le recueil légal de manière plus large**. False par défaut. Pertinent pour le futur outil `kafala-be-recueil-legal`.
            F-239 + F-241 — Champs string complémentaires (peuplent les outils pré-fill côté frontend).
              "date_accord_initial_divorce" : chaîne ISO YYYY-MM-DD ou null. **Date de signature de la pièce qui formalise l'accord initial des époux sur le divorce** (nom neutre FR+BE — F-241 a renommé l'ancienne clé `date_acceptation_pv` qui induisait un biais FR-PV). À renseigner OBLIGATOIREMENT si une telle date figure dans les pièces, dans tous les cas suivants :
                - **BE — Divorce par consentement mutuel (DC, art. 1287+ CJ)** : date de signature de la convention préalable à divorce par consentement mutuel. Indices textuels typiques : "convention préalable, datée du [date]", "Fait à [ville], le [date]" en fin de convention, "A Bruxelles, le [date]", mention "signé le [date]" sur la convention.
                - **FR — Divorce accepté (art. 233-234 Cciv)** : date de signature du procès-verbal d'acceptation du principe de la rupture devant le juge.
                - **FR — Divorce par consentement mutuel notarié (art. 229-1+ Cciv)** : date de signature de la convention de divorce par les époux et leurs avocats.
              **Exemple concret BE** : si la convention indique "Les requérants ont réglé de commun accord toutes les conséquences de leur divorce dans une convention préalable complète, datée du **12 décembre 2025**" → retourner `"2025-12-12"`. Si la convention indique "A Bruxelles, le **12 décembre 2025**" en signature → idem.
              **VALIDATION FINALE AVANT RETOUR JSON — F-241** : avant d'émettre le JSON final, relis attentivement les sections `timeline` et `faits` que tu viens de produire. **Si l'une d'elles mentionne explicitement la signature d'une convention / d'un PV / d'un accord initial à une date précise** (mots-clés "signature", "signé(e)", "datée du", "convention préalable", "convention de divorce", "procès-verbal d'acceptation"), **cette même date DOIT figurer dans `date_accord_initial_divorce`**. Ne pas peupler ce champ alors que la timeline contient cette signature = INCOHÉRENCE INTERNE à proscrire.
              **Null** uniquement si aucune date de signature de pièce d'accord initial n'est documentée (pièce non signée, date masquée, dossier purement contentieux sans accord). Pertinent pour F-FA-07 (checklist divorce) qui pré-coche 2 étapes signature quand cette date est présente.
              NB rétro-compat : l'ancienne clé `date_acceptation_pv` reste acceptée côté backend si tu l'utilises par habitude, mais privilégie `date_accord_initial_divorce` qui est le nom canonique.
            SF-246-06 — Sous-objet `succession_detection` (successions / libéralités, FRANCE UNIQUEMENT).
              "succession_detection" : objet OU null. Renseigne-le UNIQUEMENT pour un dossier de droit de la famille FRANCE comportant une succession ouverte, une donation ou un testament documentés dans les pièces (acte de notoriété, déclaration de succession, testament olographe/authentique, acte de donation, donation-partage). Pour un dossier famille BELGIQUE, ce sous-objet DOIT rester null (les successions BE relèvent du pacte successoral, géré séparément). Si aucune succession / donation / testament n'est documenté, retourne null pour tout le sous-objet. Chaque champ interne est nullable : mets null plutôt qu'une valeur approximative dès que la pièce ne permet pas une lecture certaine. Ces 16 champs peuplent le pré-remplissage des 8 outils décisionnels F-FA-24 (partage successoral, réserve héréditaire, rapport à succession, acceptation/renonciation, indivision successorale, dévolution légale, donation, validité testament). Les champs internes :
                - "date_deces" : chaîne ISO YYYY-MM-DD ou null. **Date du décès du de cujus** (date à laquelle la personne est décédée). À renseigner si elle figure dans une pièce (acte de décès, acte de notoriété). Distincte juridiquement de la date d'ouverture de la succession ci-dessous, même si elles coïncident en pratique. Null si non documentée ou illisible.
                - "date_ouverture_succession" : chaîne ISO YYYY-MM-DD ou null. **Date d'ouverture de la succession** (art. 720 Cciv — la succession s'ouvre par la mort, au dernier domicile du défunt). En pratique identique à `date_deces`, mais reste un concept distinct : ne PAS la déduire mécaniquement, ne la renseigne que si une pièce la mentionne explicitement (déclaration de succession, acte de notoriété). Null sinon.
                - "mode_partage_demande" : chaîne ou null. Mode de partage successoral demandé. Valeurs autorisées STRICTEMENT : "AMIABLE" (partage à l'amiable entre cohéritiers, art. 835 Cciv) ou "JUDICIAIRE" (partage judiciaire, art. 840 Cciv — désaccord, assignation, PV de difficultés). Toute autre valeur → null.
                - "nombre_coheritiers" : entier entre 0 et 50 ou null. Nombre total de cohéritiers appelés à la succession (y compris le client). Null si non dénombrable de façon fiable.
                - "montant_succession_eur" : nombre strictement positif (euros) ou null. Montant / valeur globale de la succession. Jamais 0 ni négatif : si le montant n'est pas chiffré dans les pièces, retourne null.
                - "montant_liberalites_total_eur" : nombre strictement positif (euros) ou null. Montant total des libéralités consenties par le défunt (donations + legs). Null si non chiffré.
                - "nombre_enfants_succession" : entier entre 0 et 50 ou null. Nombre d'enfants du défunt (héritiers réservataires descendants). Null si non dénombrable.
                - "date_donation" : chaîne ISO YYYY-MM-DD ou null. **Date de l'acte de donation** (donation entre vifs, donation-partage). Souvent ANTÉRIEURE au décès — ne la confonds pas avec `date_deces` ni `date_redaction_testament`. Null si non documentée.
                - "montant_donations_recues_eur" : nombre strictement positif (euros) ou null. Montant des donations reçues par un héritier (pour le calcul du rapport à succession, art. 843 Cciv). Null si non chiffré.
                - "valeur_donation_au_jour_partage_eur" : nombre strictement positif (euros) ou null. Valeur de la donation réévaluée au jour du partage (art. 860 Cciv — le rapport se fait d'après la valeur du bien à l'époque du partage). Null si non chiffrée.
                - "actif_brut_succession_eur" : nombre strictement positif (euros) ou null. Actif brut de la succession (total des biens, avant déduction du passif). Null si non chiffré.
                - "passif_succession_eur" : nombre strictement positif (euros) ou null. Passif de la succession (total des dettes du défunt). Null si non chiffré.
                - "type_indivision_successorale" : chaîne ou null. Type d'indivision successorale. Valeurs autorisées STRICTEMENT : "LEGALE" (indivision légale de droit commun, art. 815 Cciv) ou "CONVENTIONNELLE" (indivision organisée par convention, art. 1873-1 Cciv). Toute autre valeur → null.
                - "nb_descendants" : entier entre 0 et 50 ou null. Nombre de descendants du défunt (pour la dévolution légale, ordre des héritiers art. 734 Cciv). Null si non dénombrable.
                - "nb_freres_soeurs" : entier entre 0 et 50 ou null. Nombre de frères et sœurs du défunt (collatéraux privilégiés, dévolution légale). Null si non dénombrable.
                - "date_redaction_testament" : chaîne ISO YYYY-MM-DD ou null. **Date de rédaction du testament** (date portée sur le testament olographe, ou date de l'acte authentique). Distincte de `date_deces` et de `date_donation`. Null si le testament n'est pas daté ou non produit.
              **DISTINCTION DES DATES — règle anti-confusion** : `date_deces` (mort du de cujus), `date_ouverture_succession` (ouverture de la succession — art. 720 Cciv), `date_donation` (acte de donation, souvent antérieur au décès) et `date_redaction_testament` (rédaction du testament) sont QUATRE concepts distincts. N'affecte une date à un champ que si la pièce la rattache explicitement à ce concept. En cas de doute sur le concept visé → null.
            SF-246-07 — Sous-objet `regime_matrimonial_detection` (régimes matrimoniaux / liquidation, FRANCE UNIQUEMENT).
              "regime_matrimonial_detection" : objet OU null. Renseigne-le UNIQUEMENT pour un dossier de droit de la famille FRANCE comportant un contrat de mariage, une liquidation de régime matrimonial ou une demande de partage judiciaire entre coïndivisaires documentés dans les pièces. Pour un dossier famille BELGIQUE, ce sous-objet DOIT rester null (les régimes BE — communauté légale BE, liquidation-partage BE — sont distincts et traités séparément). Si aucun régime matrimonial / liquidation / indivision n'est documenté, retourne null pour tout le sous-objet. Chaque champ interne est nullable : mets null plutôt qu'une valeur approximative dès que la pièce ne permet pas une lecture certaine. Ces 4 champs peuplent le pré-remplissage des 3 outils décisionnels F-FA-15/16/17 (récompenses, communauté universelle, partage judiciaire). Les champs internes :
                - "regime_matrimonial" : chaîne ou null. Régime matrimonial détecté dans le contrat de mariage ou les pièces procédurales. Valeurs autorisées STRICTEMENT (correspondance avec l'énumération FR) : "COMMUNAUTE_LEGALE" (régime légal supplétif, art. 1400+ Cciv — communauté d'acquêts), "COMMUNAUTE_UNIVERSELLE" (art. 1526+ Cciv — tous les biens communs, avec ou sans clause d'attribution intégrale), "SEPARATION_BIENS" (art. 1536+ Cciv — chaque époux conserve ses biens propres), "PARTICIPATION_ACQUETS" (art. 1569+ Cciv — régime mixte : séparation pendant le mariage, participation à la dissolution). Toute autre valeur → null. Null si le régime n'est pas identifiable dans les pièces ou si le dossier est belge. NE PAS déduire mécaniquement : si le contrat de mariage n'est pas produit, n'inférer que si la procédure ou les faits permettent une identification certaine.
                - "valeur_communaute_eur" : nombre strictement positif (euros) ou null. Valeur totale de la communauté (actif commun net) détectée dans les pièces (état liquidatif, expertise, déclaration des parties). Applicable UNIQUEMENT aux régimes de communauté (COMMUNAUTE_LEGALE ou COMMUNAUTE_UNIVERSELLE) — mettre null pour SEPARATION_BIENS et PARTICIPATION_ACQUETS. Jamais 0 ni négatif : si la valeur n'est pas chiffrée dans les pièces, retourne null.
                - "valeur_biens_indivision_eur" : nombre strictement positif (euros) ou null. Valeur estimée des biens en indivision détenus par les coïndivisaires, telle que mentionnée dans les pièces (acte d'achat indivis, expertise immobilière, état liquidatif). Pertinent pour l'outil partage-judiciaire (F-FA-17, art. 840 Cciv). Null si non chiffrée ou si aucune indivision n'est documentée.
                - "nombre_coindivisaires" : entier entre 0 et 50 ou null. Nombre total de coïndivisaires (toutes les parties qui détiennent des droits indivis sur les biens — y compris le demandeur). Pertinent pour l'outil partage-judiciaire. Null si non dénombrable de façon fiable dans les pièces.
              **RÈGLE ANTI-CONFUSION régime / fait** : le champ `regime_matrimonial` reflète le régime JURIDIQUE documenté dans les pièces (contrat de mariage notarié, jugement de modification de régime), JAMAIS la qualification revendiquée par une partie. Si un époux soutient qu'une SCI constitue une mise en communauté implicite mais que le contrat de mariage prévoit la séparation de biens → `regime_matrimonial` = "SEPARATION_BIENS". La prétention juridique n'est pas un fait documenté.
            SF-246-08 — Sous-objet `vie_commune_detection` (vie commune / séparation / PACS / protection, FRANCE UNIQUEMENT).
              "vie_commune_detection" : objet OU null. Renseigne-le UNIQUEMENT pour un dossier de droit de la famille FRANCE comportant une séparation de corps, une dissolution de PACS, une demande d'ordonnance de protection, des mesures provisoires AOMP ou une révision post-divorce documentés dans les pièces. Pour un dossier famille BELGIQUE, ce sous-objet DOIT rester null (les procédures BE équivalentes sont distinctes). Si aucun des contextes ci-dessus n'est documenté, retourne null pour tout le sous-objet. Chaque champ interne est nullable : mets null plutôt qu'une valeur approximative. Ces 7 champs peuplent le pré-remplissage des 6 outils décisionnels F-FA-12/13/14/20/21/22. Les champs internes :
                - "date_separation" : chaîne ISO YYYY-MM-DD ou null. **Date de la séparation effective des époux** (date à laquelle les époux ont cessé toute vie commune — art. 237-238 Cciv pour le divorce, art. 296+ pour la séparation de corps, art. 815 pour l'indivision post-séparation). Distincte de la date de mariage, de la date de l'ordonnance de non-conciliation et de la date du jugement de divorce. Null si non documentée ou ambiguë. ATTENTION DOUBLON POTENTIEL : cette clé est `date_separation` (FR) — distincte de la clé `date_separation` de SF-246-12 (Belgique, divorce DDI BE) qui sera dans un sous-objet séparé.
                - "patrimoine_commun_eur" : nombre strictement positif (euros) ou null. Valeur estimée du patrimoine commun des époux (biens indivis détenus en commun au moment de la séparation de corps ou de l'indivision). Null si non chiffré ou si le régime est la séparation de biens. **Ne pas confondre avec le flag booléen `patrimoineCommun`** (existence d'un patrimoine commun) qui est un champ distinct.
                - "date_conclusion_pacs" : chaîne ISO YYYY-MM-DD ou null. **Date de conclusion du PACS** (date de la déclaration conjointe au greffe du tribunal, art. 515-3 Cciv). Distincte de la date de dissolution, de la date d'enregistrement et de la date de prise d'effet entre les parties. Null si le PACS n'est pas documenté ou si sa date n'est pas lisible.
                - "date_requete_op" : chaîne ISO YYYY-MM-DD ou null. **Date de dépôt de la requête en ordonnance de protection** par la partie requérante auprès du JAF (art. 515-10 Cciv). Distincte de la date de l'audience, de la date de l'ordonnance rendue et de la date de la plainte pénale. Null si la requête OP n'est pas documentée. NE PAS CONFONDRE avec `date_ordonnance_protection_jaf` (Immigration SF-246-04) qui est la date de l'ordonnance RENDUE — ici c'est la date du DÉPÔT de la requête.
                - "date_audience_aomp" : chaîne ISO YYYY-MM-DD ou null. **Date de l'audience de l'ordonnance de mesures provisoires (AOMP)** devant le JAF (art. 254-256 Cciv). Distincte de la date de dépôt de la requête, de la date de l'assignation et de la date du jugement de divorce. Null si non documentée ou si aucune AOMP n'est envisagée.
                - "nb_enfants_a_charge" : entier entre 0 et 30 ou null. Nombre d'enfants communs à charge au moment de la révision post-divorce (pension / prestation compensatoire). Null si non dénombrable de façon fiable.
                - "revenus_annuels_epoux_eur" : nombre strictement positif (euros) ou null. Revenus annuels nets de l'époux débiteur de la pension ou prestation compensatoire à réviser, tel que mentionné dans les pièces (fiche de paie, avis d'imposition, déclaration de revenus). Préciser "nets annuels" — ne pas convertir un net mensuel en annuel sauf si la pièce mentionne un revenu mensuel et que l'annuel est calculable. Null si non chiffré.
              **DISTINCTION DES DATES VIE COMMUNE — règle anti-confusion** : `date_separation` (cessation de la vie commune), `date_conclusion_pacs` (formation du PACS), `date_requete_op` (dépôt de la requête OP) et `date_audience_aomp` (audience AOMP) sont QUATRE concepts distincts. Chaque date n'est à renseigner que si la pièce la rattache explicitement à ce concept précis. En cas de doute → null.
            SF-246-09 — Sous-objet `filiation_detection` (filiation / adoption, FRANCE UNIQUEMENT).
              "filiation_detection" : objet OU null. Renseigne-le UNIQUEMENT pour un dossier de droit de la famille FRANCE comportant une question de filiation (contestation de paternité, recherche de paternité, reconnaissance paternelle) ou une procédure d'adoption documentée dans les pièces. Pour un dossier famille BELGIQUE, ce sous-objet DOIT rester null (les actions de filiation BE relèvent d'autres outils distincts). Si aucune question de filiation / adoption n'est documentée, retourne null pour tout le sous-objet. Chaque champ interne est nullable : mets null plutôt qu'une valeur approximative dès que la pièce ne permet pas une lecture certaine. Ces 7 champs peuplent le pré-remplissage des 4 outils décisionnels F-FA-18 (contestation-paternite, recherche-paternite, reconnaissance-paternelle, adoption). Les champs internes :
                - "date_etablissement_filiation" : chaîne ISO YYYY-MM-DD ou null. **Date d'établissement du lien de filiation** contesté (date de l'acte de naissance portant la filiation litigieuse, ou date de l'acte de reconnaissance antérieur). Distincte de la date de naissance de l'enfant et de la date de connaissance de la vérité. Null si non documentée ou ambiguë. Pertinent pour l'outil contestation-paternite.
                - "date_connaissance_verite" : chaîne ISO YYYY-MM-DD ou null. **Date à laquelle le demandeur a eu connaissance de la vérité sur la filiation** (point de départ du délai de prescription de 5 ans, art. 321 Cciv). Peut être la date d'un test ADN, d'un aveu, d'une révélation. Distincte de `date_etablissement_filiation` et de la date de naissance. Null si non documentée.
                - "date_majorite_enfant" : chaîne ISO YYYY-MM-DD ou null. **Date de majorité de l'enfant concerné** (18 ans à compter de la naissance — art. 388 Cciv). Pertinent pour l'enfant lui-même lorsqu'il agit (délai de 10 ans à compter de sa majorité, art. 321 Cciv). Calculable à partir de la date de naissance si celle-ci figure dans les pièces. Null sinon. Distincte de `date_etablissement_filiation` et de `date_connaissance_verite`. NE PAS CONFONDRE avec la date de naissance.
                - "date_naissance_enfant_recherche" : chaîne ISO YYYY-MM-DD ou null. **Date de naissance de l'enfant dont la paternité est recherchée** (action en recherche de paternité — art. 327 Cciv). Le délai de prescription est lié à cette naissance (10 ans à compter de la naissance pour la mère). ATTENTION : ce champ est DISTINCT de `date_naissance_enfant` ci-dessous. `date_naissance_enfant_recherche` est l'enfant d'une ACTION EN RECHERCHE DE PATERNITÉ (art. 327) ; `date_naissance_enfant` est l'enfant d'une RECONNAISSANCE PATERNELLE (art. 316). Ne jamais renseigner les deux avec la même date s'il s'agit du même enfant dans un même dossier — identifier le contexte juridique précis.
                - "date_naissance_enfant" : chaîne ISO YYYY-MM-DD ou null. **Date de naissance de l'enfant faisant l'objet d'une reconnaissance paternelle** (art. 316 Cciv). DISTINCT de `date_naissance_enfant_recherche` (action en recherche de paternité art. 327). Null si le dossier ne porte pas sur une reconnaissance paternelle ou si la date n'est pas lisible.
                - "age_adoptant" : entier entre 0 et 120 ou null. **Âge de l'adoptant en années à la date de la requête d'adoption** (conditions d'âge minimum art. 343 + al. 2 Cciv : 28 ans minimum pour l'adoptant seul, 15 ans d'écart minimum avec l'adopté). Extraire l'âge directement si mentionné ; ne pas calculer à partir d'une date de naissance sauf si le résultat est certain. Null si non déterminable. Pertinent pour l'outil adoption.
                - "age_adopte" : entier entre 0 et 120 ou null. **Âge de l'adopté en années à la date de la requête d'adoption** (adoption plénière : limite 15 ans art. 345 Cciv sauf exceptions ; adoption simple : pas de limite d'âge en principe). Extraire l'âge directement si mentionné. Null si non déterminable.
              **DISTINCTION DES DATES FILIATION — règle anti-confusion** : `date_etablissement_filiation` (acte ou reconnaissance établissant la filiation), `date_connaissance_verite` (découverte de la non-paternité par le demandeur), `date_majorite_enfant` (18 ans — départ du délai 10 ans pour l'enfant), `date_naissance_enfant_recherche` (naissance de l'enfant dans une action art. 327), `date_naissance_enfant` (naissance de l'enfant dans une reconnaissance art. 316) sont CINQ concepts distincts. Ne renseigner chaque date que si la pièce la rattache explicitement à ce concept précis. En cas de doute → null.
            SF-246-10 — Sous-objet `autorite_parentale_detection` (autorité parentale / résidence / calendrier de garde, FRANCE UNIQUEMENT).
              "autorite_parentale_detection" : objet OU null. Renseigne-le UNIQUEMENT pour un dossier de droit de la famille FRANCE comportant une question d'autorité parentale, de changement de résidence d'un enfant, d'un désaccord parental ou d'un calendrier de garde documentée dans les pièces. Pour un dossier famille BELGIQUE, ce sous-objet DOIT rester null (l'autorité parentale BE relève d'`autorite-parentale-be`, outil distinct). Si aucune question d'autorité parentale / résidence / garde n'est documentée, retourne null pour tout le sous-objet. Ces 3 champs peuplent le pré-remplissage des 4 outils décisionnels F-FA-19 (autorite-parentale, changement-residence, desaccords-parentaux, calendrier-garde). Les champs internes :
                - "ages_enfants" : tableau d'entiers ou null. **Âges en années entières des enfants concernés par la question d'autorité parentale à la date de l'analyse**, dans l'ordre de naissance (du plus âgé au plus jeune). Chaque âge doit être un entier entre 0 et 25 (inclus). Un âge non identifiable de façon fiable pour un enfant particulier est exclu du tableau plutôt que deviné. Si le tableau serait vide après filtrage → retourner null (jamais un tableau vide []). Si plusieurs enfants ont le même âge → les inclure autant de fois qu'ils existent. Null si aucun âge n'est déterminable de façon fiable.
                - "date_debut_calendrier" : chaîne ISO YYYY-MM-DD ou null. **Date de début de la période pour laquelle un calendrier de garde est demandé ou en vigueur** (ex. rentrée scolaire à venir, début d'une nouvelle ordonnance provisoire). Pertinent principalement pour l'outil calendrier-garde. Null si non documentée.
                - "date_fin_calendrier" : chaîne ISO YYYY-MM-DD ou null. **Date de fin de la période du calendrier de garde demandé ou en vigueur** (ex. fin d'année scolaire, terme d'une ordonnance provisoire). Distincte de `date_debut_calendrier`. Null si non documentée.
              **RÈGLE LISTE D'ÂGES** : un dossier de famille comporte couramment plusieurs enfants. Extraire tous les âges identifiables ; exclure un âge non fiable plutôt que de l'approximer. Si un dossier mentionne "deux enfants de 10 et 7 ans" → `[10, 7]`. Si seulement l'un des âges est mentionné → `[10]`. Si aucun âge n'est mentionné → null (jamais `[]`).
            """;

    private static final String TRAVAIL_INSTRUCTION = """

            ========== RÈGLE CRITIQUE DE CLASSIFICATION — À APPLIQUER EN PREMIER ==========
            Avant toute autre analyse, identifie le MÉCANISME FACTUEL de la rupture
            (ce qui s'est réellement passé, attesté par une pièce signée/notifiée),
            JAMAIS la qualification juridique demandée dans les arguments d'une partie.

            Procédure OBLIGATOIRE de classification (dans cet ordre strict) :
            1. Existe-t-il dans les documents une CONVENTION DE RUPTURE signée par les deux
               parties ? → OUI = "RUPTURE_CONVENTIONNELLE" (ne cherche pas plus loin, même
               si le dossier argumente la nullité pour obtenir une requalification en
               licenciement sans cause réelle). Les vices de la RC (pas d'homologation,
               délai rétractation non respecté, consentement vicié, etc.) alimenteront
               "rupture_conv_validity_detection" avec "NON" justifiés — jamais type_rupture.
            2. Existe-t-il une LETTRE DE LICENCIEMENT notifiée par l'employeur ? →
               "LICENCIEMENT" (ou "LICENCIEMENT_ECONOMIQUE" si motif économique explicite).
            3. Le salarié a-t-il pris acte de la rupture ? → "PRISE_ACTE".
            4. Y a-t-il une demande de résiliation judiciaire en cours ? → "RESILIATION_JUDICIAIRE".
            5. Lettre de démission du salarié ? → "DEMISSION".
            6. Aucun de ces faits mais une rupture est évoquée ? → Choisir la valeur la
               plus probable au vu des pièces ; ne jamais omettre.

            PIÈGE FRÉQUENT À ÉVITER : un dossier où le salarié conteste une RC en demandant
            sa REQUALIFICATION en licenciement sans cause réelle comporte souvent de
            nombreuses mentions de "licenciement" dans les conclusions/arguments. Ces
            mentions sont des DEMANDES JURIDIQUES, pas des faits. type_rupture reste
            "RUPTURE_CONVENTIONNELLE" tant que la RC n'a pas été annulée par un juge.
            ================================================================================

            Pour ce dossier de droit du travail, inclure également dans le JSON les champs suivants :
            "travail_extracted_data" : objet avec les champs :
              "convention_collective" : code identifiant la convention collective détectée. FORMAT ATTENDU : numéro IDCC officiel sur 4 chiffres préfixé par "IDCC_" (ex: "IDCC_3043" pour Propreté, "IDCC_3248" pour Métallurgie, "IDCC_1486" pour Syntec, "IDCC_2216" pour Commerce de détail). Pour la Belgique, utiliser le format "CP{numéro}" (ex: "CP200"). Si la convention est identifiable mais que son numéro IDCC exact n'est pas certain, retourner un code descriptif en MAJUSCULES (ex: "NETTOYAGE"). Retourner null si aucune convention n'est détectable.
              "date_entree" : date d'entrée dans l'entreprise au format YYYY-MM-DD, null si non détectable.
              "salaire_brut_mensuel" : salaire brut mensuel en euros (nombre). Si les documents mentionnent UNIQUEMENT un salaire net (pas de brut explicite), applique la conversion approximative brut ≈ net × 1,30 (moyenne FR non-cadre) et positionne "salaire_est_deduit": true. Si brut explicite détecté → omets "salaire_est_deduit" ou le positionnes à false. Null uniquement si AUCUN salaire (ni brut ni net) n'est détectable.
              "salaire_est_deduit" : booléen optionnel (true/false/null). True quand salaire_brut_mensuel a été déduit d'un net via la conversion × 1,30. False ou null sinon.
              "type_contrat" : type de contrat détecté ("CDI", "CDD", "INTERIM"), null si non détectable.
              "poste" : intitulé du poste occupé, null si non détectable.
              "motif_licenciement" : motif du licenciement si détecté (texte libre), null si non détectable.
              "date_licenciement" : date du licenciement ou de la rupture au format YYYY-MM-DD, null si non détectable.
              "conges_contractuels" : nombre de jours de congés prévus au contrat (entier), null si non détectable.
              "prime_anciennete_contractuelle" : pourcentage de prime d'ancienneté au contrat (nombre), null si non détectable.
              "nom_salarie" : nom de famille du salarié (texte), null si non détectable.
              "prenom_salarie" : prénom du salarié (texte), null si non détectable.
              "adresse_salarie" : adresse postale du salarié (rue + code postal + ville concaténés), null si partielle non utilisable.
              "nom_employeur" : raison sociale de l'employeur (ex: "FinConsult SPRL", "Acme SAS"). Prioriser la raison sociale sur le nom commercial. Null si non détectable.
              "adresse_employeur" : adresse du siège social de l'employeur (rue + code postal + ville concaténés). Ne pas prendre l'adresse d'une succursale. Null si non détectable.
              "siret_employeur" : numéro SIREN (9 chiffres) ou SIRET (14 chiffres) pour un employeur français uniquement. Retirer espaces et points. Null pour un dossier belge ou si non détectable.
              "bce_employeur" : numéro BCE (10 chiffres) pour un employeur belge uniquement. Retirer le préfixe "BE" et les points. Null pour un dossier français ou si non détectable.
              "representant_employeur" : nom du représentant légal ou RH signataire (ex. administrateur délégué, DRH). Null si non détectable. NE JAMAIS INVENTER un SIRET/BCE/adresse — null en cas de doute.
              "motif_nullite_pressenti" : code motif de nullité du licenciement pressenti au vu des pièces (dossiers FR de harcèlement / discrimination / rupture de contrat protégée). Utiliser EXCLUSIVEMENT l'une de ces 7 valeurs en majuscules (null si aucun indice clair ou dossier BE) : "DISCRIMINATION" (art. L.1132-1 CT, critère prohibé documenté), "HARCELEMENT_MORAL" (art. L.1152-3 CT, dénonciation ou témoignages), "HARCELEMENT_SEXUEL" (art. L.1153-3 CT), "RETORSION" (licenciement suite à dénonciation), "SYNDICAL" (art. L.2411-1 CT, représentant du personnel), "MATERNITE_PATERNITE" (art. L.1225-71 CT, grossesse / congé mat ou pat), "ACCIDENT_MP" (L.1226-9 CT, accident du travail ou maladie professionnelle). Ne jamais inventer : si le motif dominant n'est pas factuellement identifiable dans les pièces, laisser null.
              "origine_inaptitude_pressentie" : code origine de l'inaptitude pressentie au vu d'un avis du médecin du travail présent dans les pièces (dossiers FR d'inaptitude). Utiliser EXCLUSIVEMENT l'une de ces 3 valeurs (null si aucun avis ou dossier BE) : "ACCIDENT_TRAVAIL" (origine AT qualifiée), "MALADIE_PROFESSIONNELLE" (origine MP qualifiée), "MALADIE_ORDINAIRE" (maladie non professionnelle).
              "avis_medecin_travail_date" : date de l'avis d'inaptitude au format YYYY-MM-DD, null si aucun avis présent dans les pièces.
              "reclassement_respecte_detected" : objet {"reponse": "OUI"|"NON"|"INCONNU", "justification": phrase courte citant l'indice ≤ 500 car}. "OUI" si une recherche de reclassement est documentée (courriers aux postes disponibles, propositions refusées par le salarié). "NON" si l'employeur a déclaré explicitement l'impossibilité de reclassement sans documenter la recherche, ou si aucune recherche n'est mentionnée alors que le dossier est en inaptitude. "INCONNU" à défaut d'information.
              "heures_sup_mentionnees" : objet {"total_declarees_25pct": <entier ≥ 0>, "total_declarees_50pct": <entier ≥ 0>, "hors_contingent": <entier ≥ 0>} qui agrège les heures supplémentaires mentionnées dans les pièces (bulletins de paie, décomptes, attestations). Tous les champs nullables — chaque catégorie est indépendante. Null (ou objet vide) si aucune heure sup n'est évoquée. Dossiers BE : laisser null (la règlementation BE fonctionne par sursalaire forfaitaire, pas 25/50 %).
              SF-166-01 — 8 flags décisionnels niveau 3 (F-DT-20/21/24/30/31/33/34/35), FRANCE UNIQUEMENT. Chaque flag est un booléen avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces. Pour un dossier travail BELGIQUE, TOUS ces 8 flags DOIVENT rester false (les régimes BE équivalents — travail au noir, clause non-concurrence BE, délégué syndical, transaction BE, Fedris, référé président tribunal travail BE, contestation ONEM — sont distincts et seront traités séparément).
              "rappel_salaire_detecte" : booléen — true uniquement si les pièces contiennent des indices factuels d'arriérés salariaux (bulletin de paie litigieux, mise en demeure pour salaire impayé, mention "rappel de salaire" / "heures non rémunérées" / "primes contractuelles non versées" / "13e mois dû"). False par défaut, y compris si aucun indice clair. Ne jamais inventer. Pertinent pour F-DT-20.
              "travail_dissimule_detecte" : booléen — true uniquement si les pièces évoquent une dissimulation au sens art. L.8221-3+ CT (heures non déclarées, absence de DPAE, fausse qualification de poste, sous-déclaration salariale documentée, témoignages de collègues, courrier d'inspection du travail). False par défaut. Pertinent pour F-DT-21.
              "clause_non_concurrence_detectee" : booléen — true UNIQUEMENT si une clause de non-concurrence est textuellement présente dans le contrat de travail produit aux pièces (avec ou sans contrepartie financière chiffrée). False par défaut, y compris si la clause est seulement évoquée sans pièce contractuelle. Pertinent pour F-DT-24.
              "statut_protege_detecte" : booléen — true uniquement si les pièces mentionnent factuellement un statut de représentant du personnel pour le salarié (CSE titulaire ou suppléant, délégué syndical, RSS, conseiller prud'homme, conseiller du salarié, défenseur syndical, médecin du travail, ancien CHSCT — art. L.2411-1 CT). False par défaut. Pertinent pour F-DT-30.
              "transaction_envisagee" : booléen — true uniquement si une transaction post-rupture est envisagée, négociée ou signée selon les pièces (protocole transactionnel, courrier proposant une transaction, mention "concessions réciproques", "indemnité transactionnelle"). False par défaut. Pertinent pour F-DT-31.
              "at_mp_detecte" : booléen — true uniquement si le dossier contient des pièces relatives à un accident du travail ou à une maladie professionnelle (déclaration CPAM, certificat médical initial AT/MP, taux IPP fixé, contestation de reconnaissance, congé maladie professionnelle, décision CRRMP). False par défaut. Pertinent pour F-DT-33.
              "urgence_procedurale" : booléen — true uniquement si les pièces évoquent factuellement une urgence procédurale au sens du référé prud'homal (art. R.1454-1 CT) : non-paiement de salaires en cours, mise à pied conservatoire, contestation immédiate d'un licenciement nul (réintégration sans tarder), provisions à obtenir rapidement, mesures conservatoires demandées. False par défaut. Pertinent pour F-DT-34.
              "contestation_are_envisagee" : booléen — true uniquement si les pièces mentionnent un litige avec France Travail / Pôle Emploi (refus ARE notifié, recours hiérarchique formé, contestation de carence, démission requalifiée par France Travail, courrier France Travail). False par défaut. Pertinent pour F-DT-35.
              F-204 — 5 flags décisionnels niveau 3 (F-DT-11/12/15/19/27 BE), BELGIQUE UNIQUEMENT. Chaque flag est un booléen avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces. Pour un dossier travail FRANCE, TOUS ces 5 flags DOIVENT rester false (les régimes FR équivalents sont gérés par les flags FR ci-dessus, par F-DT-08 validity, ou par F-205 ultérieur).
              "harcelement_be_detecte" : booléen — true uniquement si les pièces évoquent des faits de harcèlement moral ou sexuel au travail au sens de la Loi du 4 août 1996 relative au bien-être des travailleurs (plainte formelle déposée auprès du conseiller en prévention aspects psychosociaux, témoignages de collègues, demande d'intervention psychosociale, certificat médical lien stress travail, courrier inspection sociale CBE). False par défaut. Pertinent pour F-DT-11 BE.
              "discrimination_be_detectee" : booléen — true uniquement si les pièces évoquent une discrimination au sens de la Loi du 10 mai 2007 (genre, origine, conviction religieuse, orientation sexuelle, handicap, âge, état de santé) avec indice factuel documenté (refus d'embauche, refus de promotion, licenciement sur motif protégé, courrier UNIA / Institut pour l'égalité des femmes et des hommes, témoignage). False par défaut. Pertinent pour F-DT-12 BE.
              "inaptitude_medicale_be_detectee" : booléen — true uniquement si les pièces évoquent une inaptitude médicale définitive ou un trajet de réintégration au sens de l'art. 34 Loi 03/07/1978 ou de l'AR 28/05/2003 (avis du médecin du travail, décision de force majeure médicale, plan de réintégration, refus de poste adapté). False par défaut. Pertinent pour F-DT-15 BE.
              "heures_sup_mentionnees_be" : booléen — true uniquement si les pièces évoquent factuellement des heures supplémentaires au sens de l'art. 29 Loi 16/03/1971 (sursalaire 50 % semaine ou 100 % dimanche/jours fériés, repos compensatoire dû, contestation décompte). False par défaut, y compris si le dossier mentionne uniquement la durée légale. Pertinent pour F-DT-19 BE.
              "motif_grave_be_envisage" : booléen — true uniquement si les pièces évoquent un licenciement pour motif grave au sens de l'art. 35 Loi 03/07/1978 (notification dans les 3 jours ouvrables après connaissance du fait, lettre de notification du motif dans les 3 jours suivants, contestation par le travailleur). False par défaut. Pertinent pour F-DT-27 BE.
              F-205 — 23 flags décisionnels niveau 3 additionnels FRANCE UNIQUEMENT pour préparer les outils manquants P1 (F-206) et P2 (F-212). Chaque flag est un booléen avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces. Pour un dossier travail BELGIQUE, TOUS ces 23 flags FR DOIVENT rester false (les régimes BE équivalents sont gérés par les 5 flags BE F-204 ci-dessus, ou n'ont pas d'équivalent en droit belge — c'est notamment le cas pour CSP/CRP, prise d'acte CPH, résiliation judiciaire CPH, présomption d'abandon de poste loi 21/12/2022). Cette section ne déclenche AUCUN affichage d'outil tant que F-206/F-212 n'ont pas branché les règles correspondantes.
              "abandon_poste_detecte" : booléen — true uniquement si les pièces évoquent une présomption de démission par abandon de poste au sens de la Loi 21/12/2022 (absence injustifiée du salarié, mise en demeure de l'employeur de reprendre ou justifier sous 15 jours minimum, mention "présomption de démission" / "loi 2022", contestation salarié). False par défaut.
              "arret_maladie_long_detecte" : booléen — true uniquement si les pièces évoquent un arrêt maladie de longue durée susceptible d'ouvrir le droit à acquisition de congés payés pendant l'arrêt (Loi 22/04/2024 transposant l'arrêt Cass. 13/09/2023 — rétroactivité 24 mois) : arrêts maladie cumulés, demande de rappel CP pendant arrêt maladie, mention "loi 22 avril 2024", attestation de la sécurité sociale. False par défaut.
              "prise_acte_envisagee" : booléen — true uniquement si les pièces évoquent une prise d'acte de la rupture aux torts de l'employeur (saisine CPH du salarié encore en poste, courrier salarié notifiant la prise d'acte, griefs employeur listés — manquement grave). False par défaut. NE PAS confondre avec "type_rupture": "PRISE_ACTE" qui constate le fait juridique opéré.
              "resiliation_judiciaire_envisagee" : booléen — true uniquement si les pièces évoquent une demande de résiliation judiciaire du contrat de travail aux torts de l'employeur, le salarié restant en poste (assignation devant le CPH, mémoire en demande, manquements employeur articulés — différent de la prise d'acte qui rompt immédiatement). False par défaut.
              "forfait_jours_detecte" : booléen — true uniquement si les pièces mentionnent une convention de forfait en jours sur l'année au sens des art. L.3121-58+ CT (clause contractuelle "forfait jours", "convention forfait", nombre de jours travaillés/an, accord collectif applicable Syntec / Métallurgie / etc.). False par défaut.
              "transfert_entreprise_detecte" : booléen — true uniquement si les pièces évoquent un transfert d'entreprise au sens de l'art. L.1224-1 CT (rachat, fusion, cession de fonds de commerce, scission, reprise d'activité, mention "transfert automatique des contrats", "L. 1224-1"). False par défaut.
              "faute_inexcusable_envisagee" : booléen — true uniquement si les pièces évoquent une action en reconnaissance de faute inexcusable de l'employeur au sens de l'art. L.452-1 CSS (manquement à l'obligation de sécurité, danger connu non prévenu, saisine du pôle social du tribunal judiciaire, demande de majoration de rente AT/MP). False par défaut. Sub-flag de "at_mp_detecte" — peut être true seulement si at_mp_detecte est aussi true.
              "cs_crp_envisage" : booléen — true uniquement si les pièces évoquent un Contrat de Sécurisation Professionnelle (CSP) ou son ancêtre la CRP au sens des art. L.1233-65+ CT (proposition employeur dans le cadre d'un licenciement économique, formulaire CSP signé ou refusé par le salarié, mention "CSP" / "ASP" / "Pôle Emploi convention CSP"). False par défaut. Pertinent pour F-DT-44.
              "csp_propose" : booléen — true uniquement si l'employeur a explicitement PROPOSÉ un CSP au salarié (entretien préalable mentionnant le CSP, document de proposition CSP remis, attestation de remise du document d'information CSP). Distinct de "cs_crp_envisage" qui couvre l'envisage stratégique côté avocat — ici on factualise la proposition employeur. False par défaut.
              "mutation_refusee" : booléen — true uniquement si les pièces évoquent une mutation imposée par l'employeur sur le fondement d'une clause de mobilité refusée par le salarié (clause mobilité contractuelle citée, courrier de mutation, refus écrit du salarié, lettre de licenciement consécutive éventuelle). False par défaut. Pertinent pour F-DT-71.
              "modification_contrat_refusee" : booléen — true uniquement si les pièces évoquent une proposition de modification du contrat (rémunération, durée du travail, qualification, lieu de travail) refusée par le salarié (avenant proposé, courrier de refus, courrier subséquent employeur). False par défaut. Pertinent pour F-DT-70.
              "faute_grave_envisagee" : booléen — true uniquement si les pièces évoquent une faute grave reprochée au salarié au sens de la jurisprudence (faute rendant impossible le maintien du salarié dans l'entreprise même pendant la durée du préavis : insubordination répétée, vol, violence, abandon de poste fautif, mise à pied conservatoire). False par défaut. Distinct de "faute_lourde_envisagee" (intention de nuire).
              "faute_lourde_envisagee" : booléen — true uniquement si les pièces évoquent une faute lourde caractérisée par l'intention de nuire à l'employeur (sabotage, divulgation de secrets, concurrence déloyale active pendant le contrat, vol qualifié), avec privation de l'indemnité de congés payés. False par défaut.
              "cdd_requalification_envisagee" : booléen — true uniquement si le dossier vise la requalification d'un CDD ou d'une succession de CDD en CDI au sens des art. L.1245-1+ CT (motif de recours discutable, dépassement de la durée maximale, succession de CDD sans interruption, absence d'écrit, transmission tardive). False par défaut. Pertinent pour F-DT-43.
              "interim_requalification_envisagee" : booléen — true uniquement si le dossier vise la requalification d'une mission d'intérim en CDI au sens des art. L.1251-40+ CT (motifs de recours non prévus, dépassement de durée, succession sans délai de carence, absence de contrat de mise à disposition). False par défaut.
              "forfait_jours_validite_contestee" : booléen — true uniquement si le dossier conteste la validité du forfait jours (Cass. 29/06/2011, Syntec) : absence de suivi régulier de la charge de travail, absence d'entretien annuel, accord collectif insuffisant, dépassement régulier des 218 jours sans contrepartie. False par défaut. Distinct de "forfait_jours_detecte" qui factualise la simple existence du forfait.
              "prescription_proche_detectee" : booléen — true uniquement si les pièces font apparaître que l'action envisagée approche de sa prescription (1 an post-rupture pour contester un licenciement L.1471-1 CT, 2 ans pour exécution du contrat hors salaire, 3 ans pour rappel de salaire L.3245-1 CT, 5 ans pour discrimination/harcèlement/dommages corporels). Mention de date butoir, courrier rappelant le délai, urgence procédurale prescription. False par défaut.
              "rupture_amiable_negociee" : booléen — true uniquement si les pièces évoquent une rupture amiable négociée du CDI distincte de la rupture conventionnelle homologuée (accord verbal/écrit en cours, courrier de proposition non finalisé, médiation interne). False par défaut. Distinct de "type_rupture": "RUPTURE_CONVENTIONNELLE" qui constate le mécanisme L.1237-11 CT signé.
              "entretien_preavis_obtenu" : booléen — true uniquement si les pièces évoquent l'organisation effective d'un entretien lié au préavis ou au CSP (entretien CSP, entretien fin de préavis, courrier de convocation, compte-rendu signé). False par défaut. Pertinent pour F-DT-44 conformité CSP.
              "cse_consultation_demandee" : booléen — true uniquement si les pièces évoquent une consultation du CSE sur un projet impactant la collectivité (PSE, PDV, RCC, accord de performance, transfert d'entreprise) ou une contestation de défaut de consultation (réunion CSE actée, ordre du jour, avis CSE rendu, courrier dénonçant l'absence de consultation). False par défaut.
              "irp_election_demandee" : booléen — true uniquement si les pièces évoquent une procédure d'élections IRP / CSE en cours ou contestée (PAP — protocole d'accord préélectoral, contestation des élections devant le tribunal judiciaire, demande d'organisation des élections par le salarié ou un syndicat). False par défaut. Pertinent pour F-DT-65.
              "inspection_travail_saisie" : booléen — true uniquement si les pièces évoquent une saisine effective de l'inspection du travail (courrier à l'inspection, procès-verbal d'inspection, mise en demeure inspection, signalement déposé). False par défaut.
              "mediation_judiciaire_envisagee" : booléen — true uniquement si les pièces évoquent une médiation préalable ou en cours d'instance prud'homale (proposition de médiation par le bureau de conciliation, désignation d'un médiateur judiciaire, accord de médiation négocié). False par défaut. Distinct de la conciliation obligatoire devant le BCO du CPH.
              "procedure_licenciement_detection" : objet REGROUPANT les indices procéduraux factuels du licenciement, pour le pré-remplissage de l'outil de nullité de procédure. FRANCE UNIQUEMENT — pour un dossier travail BELGIQUE, OMETTRE entièrement cet objet ou laisser tous ses champs à null (la procédure FR — entretien préalable, délai de 5 jours ouvrables, lettre motivée — n'a pas d'équivalent direct en droit belge). Ne renseigner un champ QUE si une pièce du dossier le documente factuellement ; à défaut de certitude, laisser le champ à null. Les 7 clés attendues :
                "convocation_entretien_detectee" : booléen — true si une lettre de convocation à entretien préalable (art. L.1232-2 CT) est présente aux pièces ou explicitement mentionnée comme reçue par le salarié. false si les pièces établissent qu'aucune convocation n'a été adressée (ex. licenciement notifié sans entretien). null si les pièces ne permettent pas de trancher.
                "date_convocation_entretien" : date de présentation / réception de la convocation à l'entretien préalable au format YYYY-MM-DD strict. null si non détectable. NE PAS confondre avec la date de l'entretien lui-même ni avec la date de notification du licenciement.
                "date_entretien_prealable" : date à laquelle l'entretien préalable s'est tenu (ou était fixé), au format YYYY-MM-DD strict. null si non détectable. Cette date est postérieure à date_convocation_entretien et antérieure à la date de notification du licenciement.
                "entretien_prealable_tenu" : objet {"reponse": "OUI"|"NON"|"INCONNU", "justification": phrase courte citant l'indice ≤ 500 car}. "OUI" si une pièce atteste que l'entretien préalable a effectivement eu lieu (compte-rendu d'entretien, courrier postérieur s'y référant, attestation). "NON" si les pièces établissent que l'entretien n'a pas été tenu (licenciement notifié sans entretien, salarié absent sans report). "INCONNU" à défaut d'information.
                "lettre_licenciement_ecrite" : booléen — true si une lettre de licenciement écrite (art. L.1232-6 CT) est présente aux pièces. false si la rupture a été notifiée sans écrit. null si non détectable.
                "lettre_licenciement_motivee" : objet {"reponse": "OUI"|"NON"|"INCONNU", "justification": phrase courte citant l'indice ≤ 500 car}. "OUI" si la lettre de licenciement énonce un ou plusieurs motifs. "NON" si la lettre est dépourvue de tout motif. "INCONNU" si la lettre n'est pas produite ou si son contenu n'est pas analysable.
                "motivation_lettre_suffisante" : objet {"reponse": "OUI"|"NON"|"INCONNU", "justification": phrase courte citant l'indice ≤ 500 car}. Apprécie si les motifs énoncés sont précis et matériellement vérifiables (art. L.1235-2 CT). "OUI" si la lettre articule des faits précis, datés et objectifs. "NON" si la lettre se borne à un motif vague (ex. "motif personnel", "insuffisance professionnelle" sans fait articulé). "INCONNU" à défaut d'analyse possible.
              "clause_non_concurrence_detail" : objet REGROUPANT le détail de la clause de non-concurrence, pour le pré-remplissage de l'outil de validité de clause de non-concurrence. FRANCE UNIQUEMENT — pour un dossier travail BELGIQUE, OMETTRE entièrement cet objet ou laisser tous ses champs à null (la clause de non-concurrence belge — CCT n°1bis, conditions de validité distinctes — relève d'un outil dédié). N'émettre cet objet QUE si une clause de non-concurrence est textuellement présente dans le contrat de travail produit aux pièces (même critère que "clause_non_concurrence_detectee"). Ne renseigner un champ QUE si la clause le stipule explicitement ; à défaut de certitude, laisser le champ à null. Les 5 clés attendues :
                "duree_mois" : durée d'application de la clause de non-concurrence exprimée en NOMBRE DE MOIS (entier). NE PAS confondre avec la durée du contrat de travail, la durée du préavis ou l'ancienneté : il s'agit exclusivement de la période pendant laquelle l'ancien salarié s'engage à ne pas concurrencer l'employeur après la rupture. Convertir en mois si la clause exprime la durée en années (ex. "2 ans" → 24). null si la clause ne chiffre pas sa durée ou si la durée n'est pas lisible avec certitude. Valeur attendue entre 0 et 600 ; toute valeur hors de cette plage sera ignorée.
                "zone_geographique" : description textuelle de la zone géographique couverte par l'interdiction de concurrence, telle que stipulée dans la clause (ex. "France métropolitaine", "départements 75, 92, 93, 94", "rayon de 50 km autour de Lyon"). Reprendre le libellé de la clause sans le reformuler. null si la clause ne délimite aucune zone géographique ou si elle n'est pas lisible. 500 caractères maximum.
                "contrepartie_montant_mensuel_eur" : montant MENSUEL de la contrepartie financière de la clause de non-concurrence, exprimé en EUROS BRUTS (nombre). RÈGLE DE CONVERSION OBLIGATOIRE : si la clause exprime la contrepartie en POURCENTAGE du salaire (ex. "30 % du salaire mensuel brut"), appliquer la conversion montant = pourcentage × salaire_brut_mensuel en utilisant la valeur de "salaire_brut_mensuel" extraite plus haut (ex. 30 % d'un salaire de 3000 € → 900.0). Si la contrepartie est exprimée en pourcentage mais que le salaire brut mensuel n'est pas identifiable, laisser null. Si la clause exprime un montant global pour toute la durée de la clause, le ramener au mois en le divisant par "duree_mois". La contrepartie est toujours BRUTE, cohérente avec "salaire_brut_mensuel". null si la clause ne prévoit aucune contrepartie financière ou si le montant n'est pas calculable de façon fiable.
                "date_prise_effet" : date de PRISE D'EFFET de la clause de non-concurrence au format YYYY-MM-DD strict, c'est-à-dire la date à partir de laquelle l'ancien salarié est tenu par l'obligation de non-concurrence. En pratique, cette date correspond à la DATE DE FIN / RUPTURE du contrat de travail (date de fin de préavis, date de notification du licenciement avec dispense de préavis, date d'effet de la rupture conventionnelle), telle qu'elle ressort de la lettre de licenciement, de la convention de rupture ou du contrat. NE PAS confondre avec la date de signature du contrat de travail, la date d'embauche, ni la date de convocation à l'entretien préalable. null si la date de fin du contrat n'est pas datée de façon fiable dans les pièces.
                "secteur_activite" : secteur d'activité de l'entreprise employeur, qui module les seuils jurisprudentiels de proportionnalité de la contrepartie. CLASSER OBLIGATOIREMENT dans l'une de ces 5 valeurs EXACTES : "INFORMATIQUE" (informatique, édition logicielle, services numériques, IT), "COMMERCE" (commerce, distribution, vente, négoce), "INDUSTRIE" (industrie, production, fabrication, BTP), "SERVICES" (services aux entreprises ou aux particuliers non couverts par les autres catégories), "AUTRE" (secteur ne correspondant clairement à aucune des 4 catégories ci-dessus). "AUTRE" n'est PAS une valeur de doute : ne l'utiliser que si le secteur est identifié mais ne rentre dans aucune des 4 catégories. Si le secteur de l'employeur n'est pas identifiable avec certitude dans les pièces, laisser null — ne JAMAIS renvoyer "AUTRE" pour signifier "inconnu".
              SF-246-05 — champ IA BELGIQUE UNIQUEMENT pour le pré-remplissage de l'outil décisionnel de crédit-temps fin de carrière (CCT n°103 et AR 29/10/1997 — conditions d'âge et d'ancienneté). Pour un dossier de droit du travail FRANÇAIS, laisser ce champ à null (le crédit-temps fin de carrière est un dispositif belge sans équivalent dans cet outil).
              "age_demandeur_annees" : âge en ANNÉES RÉVOLUES du travailleur qui demande le crédit-temps fin de carrière, à la date de sa demande de crédit-temps (entier). NE PAS confondre avec l'ancienneté du travailleur dans l'entreprise, la durée du contrat de travail, ni aucune autre durée du dossier : il s'agit exclusivement de l'âge de la personne physique demandeuse (sa date de naissance, son année de naissance, ou un âge explicitement mentionné dans les pièces). Si seule la date de naissance est disponible, calculer l'âge en années révolues à la date de la demande de crédit-temps. Valeur attendue entre 0 et 100 ; toute valeur hors de cette plage sera ignorée. null si l'âge du demandeur n'est pas déterminable de façon fiable dans les pièces, ou pour un dossier de droit du travail français. Ne JAMAIS renvoyer 0 pour signifier "inconnu" : en cas de doute, renvoyer null.
            "licenciement_validity_detection" : objet qui, à partir des documents, évalue chaque critère de validité du licenciement. Chaque valeur est un objet {reponse, justification} où reponse est l'une de "OUI", "NON", "INCONNU" (utiliser "INCONNU" si les documents ne permettent pas de trancher) et justification est une courte phrase (≤ 500 caractères) citant le document ou l'extrait qui soutient la réponse (chaîne vide acceptée). Champs attendus :
              "FR_CONVOCATION" : lettre de convocation à entretien préalable remise/envoyée avec délai minimal de 5 jours ouvrables.
              "FR_ENTRETIEN" : entretien préalable effectivement tenu, avec information sur le droit d'être assisté.
              "FR_DELAI_NOTIFICATION" : notification du licenciement dans le délai légal après l'entretien (2 jours ouvrables minimum, 7 pour licenciement économique ou cadres).
              "FR_MOTIVATION" : lettre de licenciement écrite énonçant des motifs précis (pas de motif vague).
              "FR_MOTIF_REEL" : motif réel et sérieux (objectif, exact, suffisamment grave) identifiable dans les documents.
              "FR_PROCEDURE_DISCIPLINAIRE" : délai de prescription de 2 mois entre connaissance des faits et sanction respecté, pas de double sanction.
              "FR_ORDRE_LICENCIEMENT" : pour un licenciement économique, ordre des licenciements fondé sur ancienneté, situation familiale, qualités professionnelles.
              "BE_NOTIFICATION" : notification par lettre recommandée ou exploit d'huissier.
              "BE_PREAVIS" : préavis respecté selon la loi 2013 (ou indemnité compensatoire si rupture immédiate).
              "BE_MOTIVATION" : motivation conforme CCT 109 (comportement, aptitude, ou nécessité de l'entreprise).
              "BE_AUDITION" : audition préalable tenue (recommandée mais non obligatoire — "OUI" même si audition non nécessaire).
              "BE_NON_DISCRIMINATION" : absence de motif discriminatoire (genre, âge, origine, convictions, état de santé, etc.).
              "BE_PROTECTION_SPECIALE" : aucune protection spéciale violée (délégué syndical, femme enceinte, congé parental, etc.).
              "BE_INDEMNITE_MANIFESTE" : licenciement non manifestement déraisonnable au sens CCT 109 (risque d'indemnité 3 à 17 semaines).
            Pour un dossier français, remplir prioritairement les clés FR_* ; pour un dossier belge, les clés BE_*. Les clés de l'autre pays peuvent être omises ou à "INCONNU". Si aucune évaluation n'est possible, laisser l'objet vide ({}) ou omettre entièrement.
            "compensation_data" : objet décrivant la rupture du contrat pour alimenter le comparateur d'indemnités F-DT-09. Obligatoire dès qu'une rupture du contrat est identifiée dans les documents (même si ancienneté/salaire inconnus). Mettre à null UNIQUEMENT si aucune rupture n'est évoquée. Champs :
              "type_rupture" : type de rupture, l'une de ces valeurs exactes. RÈGLE IMPÉRATIVE : le type reflète le MÉCANISME FACTUEL de la rupture (ce qui s'est passé, attesté par les pièces), JAMAIS la qualification demandée en justice.
                Exemples critiques :
                - Convention de rupture signée par les deux parties + arguments de nullité pour obtenir une requalification en licenciement sans cause réelle → "RUPTURE_CONVENTIONNELLE" (la RC existe factuellement, la requalification est une conséquence juridique visée, pas un fait). Les vices identifiés (homologation absente, délai rétractation non respecté, consentement vicié, etc.) alimenteront "rupture_conv_validity_detection" avec réponses "NON" justifiées.
                - Prise d'acte ou résiliation judiciaire demandée par le salarié alors que le contrat est encore en cours → "PRISE_ACTE" ou "RESILIATION_JUDICIAIRE" selon la voie choisie, pas "LICENCIEMENT".
                - Lettre de licenciement notifiée, peu importe les arguments de contestation → "LICENCIEMENT" (ou "LICENCIEMENT_ECONOMIQUE").
                Priorité factuelle (du plus fort au plus faible) : pièce signée/notifiée engageant juridiquement > décision administrative (DREETS, CSE) > décision judiciaire > allégation.
                France : "LICENCIEMENT" (cause réelle et sérieuse, sans faute grave), "LICENCIEMENT_ECONOMIQUE", "RUPTURE_CONVENTIONNELLE", "DEMISSION", "PRISE_ACTE", "RESILIATION_JUDICIAIRE".
                Belgique : "LICENCIEMENT_ORDINAIRE" (tout licenciement côté employeur quelle que soit la motivation — économique, disciplinaire, etc. ; "manifestement déraisonnable" est une qualification CCT 109 art. 8, pas une nature de rupture, donc utilise "LICENCIEMENT_ORDINAIRE" dans ce cas-là aussi), "RUPTURE_AMIABLE", "DEMISSION".
                Ce champ est obligatoire si compensation_data est émis. Ne jamais renvoyer null ici ; si le type est incertain, choisir la valeur la plus probable au vu des pièces, jamais omettre.
              "anciennete_annees" : ancienneté (entier), null si non détectable.
              "anciennete_mois" : ancienneté mois complémentaire (entier), null si non détectable.
              "salaire_reference_mensuel" : salaire brut mensuel moyen de référence (décimal), null si non détectable.
              En cas de ruptures multiples, retenir la plus récente (celle qui fonde la saisine actuelle).
              Exemple positif : une lettre de licenciement pour faute simple → {"type_rupture": "LICENCIEMENT", ...}. Exemple négatif : dossier harcèlement sans rupture évoquée → "compensation_data": null.
            "rupture_conv_validity_detection" : objet à ÉMETTRE UNIQUEMENT si compensation_data.type_rupture vaut "RUPTURE_CONVENTIONNELLE". Évalue les 6 critères de validité de la rupture conventionnelle (art. L1237-11 s.). Chaque valeur est un objet {reponse, justification} où reponse vaut "OUI" / "NON" / "INCONNU" et justification (≤ 500 caractères) cite brièvement le document ou l'indice qui soutient la réponse. Champs attendus :
              "RC_CONSENTEMENT" : consentement libre et éclairé. "OUI" si aucun élément n'évoque pression, dol, menace, erreur. "NON" si vice du consentement évoqué dans les pièces. "INCONNU" sinon.
              "RC_DELAI_RETRACTATION" : délai de 15 jours calendaires respecté entre signature de la convention et demande d'homologation. "OUI" si ≥ 15 jours, "NON" si < 15 jours, "INCONNU" si dates manquantes.
              "RC_HOMOLOGATION" : homologation par la DREETS (ex-DIRECCTE) obtenue ou réputée acquise. "OUI" si pièce d'homologation présente, "NON" si refus documenté, "INCONNU" à défaut.
              "RC_ASSISTANCE" : assistance possible documentée (avocat, conseiller du salarié, représentant du personnel). "OUI" si documentée, "NON" si l'employeur l'a refusée, "INCONNU" sinon.
              "RC_INDEMNITE" : indemnité spécifique supérieure ou égale à l'indemnité légale de licenciement. "OUI" si les deux montants sont connus et indemnité spécifique ≥ légale. "NON" si strictement inférieure. "INCONNU" si un montant manque.
              "RC_ENTRETIENS" : au moins un entretien préalable tenu et documenté (compte-rendu ou correspondance). "OUI" si trace écrite, "NON" si aucune, "INCONNU" sinon.
            """;

    private static final String IMMIGRATION_INSTRUCTION = """

            ========== RÈGLE CRITIQUE DE CLASSIFICATION — À APPLIQUER EN PREMIER ==========
            Identifier le MÉCANISME FACTUEL (pièce signée / décision notifiée),
            JAMAIS la qualification demandée dans les arguments d'une partie.

            Exemples critiques :
            - Refus OFPRA notifié + arguments pour recours CNDA non encore déposé →
              type_procedure_detectee = DEMANDE_ASILE_OFPRA (état actuel), type_recours_code
              reste null tant que le recours n'est pas formellement introduit (date de dépôt).
              Une fois le recours déposé : type_procedure_detectee = RECOURS_CNDA.
            - Titre de séjour temporaire en cours de validité + demande de renouvellement
              déposée → type_titre_sejour_code reflète le TITRE ACTUEL (ex. VLS_TS_SALARIE),
              pas le titre demandé. type_procedure_detectee = RENOUVELLEMENT_TITRE_SEJOUR.
            - OQTF reçue + arguments pour recours contentieux TA non encore introduit →
              type_procedure_detectee reste null (ou DEMANDE_ASILE_OFPRA selon contexte) ;
              type_recours_code = RECOURS_CONTENTIEUX_TA seulement si le recours est déposé
              ou immédiatement sur le point de l'être (pièce rédigée au dossier).
            ================================================================================

            Pour ce dossier de droit de l'immigration, inclure également dans le JSON les champs suivants :
            "date_expiration_titre" : date d'expiration du titre de séjour au format YYYY-MM-DD, null si non détectable.
            "type_titre_sejour" : type du titre de séjour en texte libre (ex: "Carte de résident", "Titre de séjour temporaire"), null si non détectable.
            "type_titre_sejour_code" : code normalisé du titre de séjour détecté, l'un des 21 codes exacts (null si non déterminable avec certitude) : "VLS_TS_ETUDIANT", "VLS_TS_SALARIE", "CST_SALARIE", "CARTE_PLURIANNUELLE", "CARTE_PLURIANNUELLE_ETUDIANT_RECHERCHE", "CARTE_PLURIANNUELLE_SALARIE", "CARTE_PLURIANNUELLE_PASSEPORT_TALENT", "CARTE_PLURIANNUELLE_VPF", "CARTE_RESIDENT", "APS", "CST_VPF", "CST_VPF_CONJOINT_FR", "RECEPISSE_ASILE" (France), "CARTE_A_TRAVAIL", "CARTE_A_ETUDES", "CARTE_A_FAMILLE", "CARTE_B", "CARTE_C", "PERMIS_UNIQUE", "ANNEXE_15", "ATTESTATION_IMMATRICULATION" (Belgique).
            RÈGLES DE PRÉCISION SF-IM-07-04 (France) — NE PAS utiliser les codes génériques "CARTE_PLURIANNUELLE" et "CST_VPF" si la mention précise du motif est lisible dans les pièces. Préférer TOUJOURS le sous-type :
            • Carte pluriannuelle + mention "Étudiant" ou "Étudiant-Recherche" → "CARTE_PLURIANNUELLE_ETUDIANT_RECHERCHE" (régime 964 h/an)
            • Carte pluriannuelle + mention "Salarié" (hors Passeport Talent) → "CARTE_PLURIANNUELLE_SALARIE"
            • Carte pluriannuelle + mention "Passeport Talent" / "Chercheur" L.421-14 / "Cadre supérieur" L.421-9 / "Créateur d'entreprise" → "CARTE_PLURIANNUELLE_PASSEPORT_TALENT"
            SF-IM-10-01 — Quand "type_titre_sejour_code" = "CARTE_PLURIANNUELLE_PASSEPORT_TALENT", ajouter le champ "talent_sub_category_code" pour préciser la sous-catégorie CESEDA (null si non déterminable) : "TALENT_CHERCHEUR" (L.421-14, convention d'accueil recherche), "TALENT_SALARIE_QUALIFIE" (L.421-9, salaire ≥ 2× SMIC + master), "TALENT_ENTREPRENEUR" (L.421-10, création entreprise + invest ≥ 30 000 €), "TALENT_INNOVANT" (L.421-11, projet innovant reconnu DGE/French Tech), "TALENT_INVESTISSEUR" (L.421-12, invest direct ≥ 300 000 €), "TALENT_PROFESSION_ARTISTIQUE" (L.421-13, artiste/créateur culturel), "TALENT_RENOMMEE_INTERNATIONALE" (L.421-13 al. 3, prix/palmarès/grands concours/JO), "TALENT_SALARIE_EN_MISSION" (L.421-15, mission ICT intra-groupe), "TALENT_FAMILLE" (L.421-22, conjoint/enfant d'un bénéficiaire Passeport Talent). Si ambigu, laisser null — le type générique "PASSEPORT_TALENT" fera fallback.
            • Carte pluriannuelle + mention "Vie privée et familiale" / "VPF" → "CARTE_PLURIANNUELLE_VPF"
            • Carte VPF 1 an délivrée au conjoint d'un ressortissant FRANÇAIS (art. L.423-1, indices : acte de mariage avec conjoint français présent au dossier) → "CST_VPF_CONJOINT_FR" (pas "CST_VPF" générique)
            Les codes génériques "CARTE_PLURIANNUELLE" et "CST_VPF" ne sont utilisés que si le motif exact n'est pas déterminable depuis les pièces.
            Si le pays ou le type ne correspond pas à cette liste, laisser null — le champ "type_titre_sejour" libre suffit pour l'affichage.
            "nationalite_ue" : booléen — true si le ressortissant est citoyen de l'Union européenne, EEE (Norvège/Islande/Liechtenstein) ou Suisse ; false s'il est ressortissant d'un pays tiers ; null si non déterminable.
            "nationalite" : nationalité du ressortissant en texte libre (adjectif féminin, ex. "Algérienne", "Tunisienne", "Marocaine", "Sénégalaise", "Française"). Null si non déterminable. Utilisé par F-IA-04 pour activer les outils décisionnels conditionnés à un régime national bilatéral (ex. F-IM-17 régime franco-algérien — Accord du 27/12/1968).
            "type_procedure_detectee" : type de procédure administrative en cours, l'une de ces valeurs exactes : "RENOUVELLEMENT_TITRE_SEJOUR", "DEMANDE_ASILE_OFPRA", "RECOURS_CNDA", "REGROUPEMENT_FAMILIAL" (R.434-35), "NATURALISATION_DECRET" (art. 21-15 CCiv), "CHANGEMENT_STATUT" (L.412-1, ex. étudiant → salarié), "AES_SALARIE" (circulaire Valls 28/11/2012, 5 ans présence + 24 mois salariat), "REGULARISATION_EXCEPTIONNELLE" (L.435-1, liens personnels et familiaux, voie humanitaire), "OQTF_AVEC_DELAI" (L.614-5, OQTF avec délai de départ volontaire 30 j), "OQTF_SANS_DELAI" (L.731-1, OQTF sans DDV, procédure JLD 48 h), null si non détectable.
            "date_depot_procedure" : date de dépôt de la demande ou du recours au format YYYY-MM-DD, null si non détectable.
            "type_recours_code" : code normalisé du recours à former ou déjà formé, l'un des 6 codes exacts (null si non déterminable avec certitude) : "RECOURS_GRACIEUX_PREFET", "RECOURS_CONTENTIEUX_TA", "RECOURS_CNDA" (France), "RECOURS_CGRA", "RECOURS_CCE", "RECOURS_CE_BELGIQUE" (Belgique). Ce champ complète "type_procedure_detectee" avec la granularité nécessaire à F-IM-06 (générateur de recours). Si la procédure est un renouvellement ou une demande d'asile OFPRA (pas un recours), laisser null.
            "date_notification_decision_contestee" : date de la décision administrative que l'on attaque par recours (refus de titre, rejet OFPRA, etc.), format YYYY-MM-DD, null si non détectable. À ne pas confondre avec "date_depot_procedure" (date de dépôt effectif du recours) ni "date_expiration_titre".
            SF-246-04 — champ IA FRANCE UNIQUEMENT pour pré-fill de l'outil décisionnel F-IM-24 (victime de violences, titre de séjour CESEDA L.425-6).
            "date_ordonnance_protection_jaf" : date de l'ordonnance de protection rendue par le juge aux affaires familiales (Code civil art. 515-9 à 515-13) au bénéfice de la victime de violences conjugales ou intrafamiliales, au format YYYY-MM-DD. Null si aucune ordonnance de protection JAF n'est présente dans les pièces, si la date n'est pas lisible avec certitude, ou pour un dossier d'immigration BELGE (dispositif propre à la France). Ne JAMAIS renvoyer une date approximative : en cas de doute ou de format ambigu, renvoyer null. À ne pas confondre avec "date_expiration_titre" (date d'expiration du titre de séjour) ni avec "date_depot_procedure" (date de dépôt de la demande ou du recours) — la date demandée ici est exclusivement celle de l'ordonnance de protection prononcée par le JAF.
            SF-155-04-00-BE-immig-FR — 5 champs IA FRANCE UNIQUEMENT pour pré-fill outils décisionnels OQTF (F-IM-08-02 OQTF avec délai, F-IM-08-04 OQTF sans délai urgence 48h). Tous ces champs DOIVENT rester null pour un dossier immigration BELGIQUE (les équivalents Annexe 13 sont traités par les 4 champs BE ci-dessous).
            "date_notification_oqtf" : date de notification de l'OQTF avec délai (arrêté préfectoral L.614-5) au format YYYY-MM-DD. Null si dossier non concerné par une OQTF avec délai ou si la date n'est pas lisible dans les pièces. Dossier belge → null.
            "motif_oqtf_code" : motif de l'OQTF avec délai détecté dans l'arrêté préfectoral, l'une de ces valeurs exactes (null si indéterminable avec certitude ou dossier belge) : "REFUS_TITRE" (refus de délivrance/renouvellement d'un titre de séjour), "EXPIRATION_TITRE" (titre de séjour expiré sans renouvellement), "SEJOUR_IRREGULIER" (entrée ou séjour irrégulier sans titre initial), "RETRAIT_TITRE" (retrait/abrogation d'un titre antérieurement délivré), "AUTRE" (motif présent mais non classable dans les 4 ci-dessus). Ne pas confondre avec les motifs d'OQTF sans délai (risque de fuite, trouble à l'ordre public, etc.) — ces derniers ne sont PAS demandés dans ce champ.
            "recours_forme_detected" : objet {"reponse": "OUI" | "NON" | "INCONNU", "justification": phrase courte (≤ 500 car.) citant l'indice textuel} indiquant si un recours contentieux contre l'OQTF a déjà été introduit au moment de l'analyse. "OUI" si une requête TA, un mémoire ou un accusé de réception greffe est présent ; "NON" si les pièces indiquent explicitement qu'aucun recours n'a encore été déposé ; "INCONNU" si les pièces ne permettent pas de trancher. Pertinent pour F-IM-08-02 et F-IM-08-04. Null pour dossier belge ou hors OQTF.
            "date_heure_notification_oqtf_sans_delai" : horodatage précis (format ISO "YYYY-MM-DDTHH:mm" ou "YYYY-MM-DDTHH:mm:ss") de la notification de l'OQTF sans délai (arrêté préfectoral L.731-1). L'heure est capitale car le délai de recours est de 48 heures devant le JLD. Null si dossier non concerné par une OQTF sans délai, si seule la date (sans heure) est détectable, ou pour un dossier belge.
            "placement_cra_detected" : booléen — true si l'arrêté mentionne un placement en centre de rétention administrative (CRA) concomitant à l'OQTF sans délai, false si le dossier précise une assignation à résidence ou absence de placement, null si non déterminable ou dossier belge. Important pour le calcul de l'urgence F-IM-08-04.
            SF-155-04-00-BE-immig-BE — 4 champs BE Annexe 13 (F-IM-08) — DOSSIERS BELGIQUE UNIQUEMENT. Pour un dossier FRANCE, laisser ces 4 champs à null (les champs OQTF FR sont gérés séparément dans le même objet).
            "date_notification_annexe13" : date de notification de l'Annexe 13 / OQT belge au format YYYY-MM-DD, null si aucune annexe 13 n'est présente ou non détectable. L'annexe 13 est la décision administrative de l'Office des étrangers (OE) ordonnant de quitter le territoire (art. 7, 74/14 Loi du 15/12/1980). Dossiers FR : null.
            "delai_depart_impose_jours" : délai de départ volontaire imposé par l'OE (entier ≥ 0). Valeurs typiques : 0 (OQT sans délai, procédure d'urgence art. 74/14 §3), 7 (délai réduit), 30 (délai standard art. 74/14 §1). Null si pas d'OQT ou délai non identifiable. Dossiers FR : null.
            "motif_oqt_code_be" : code motif factuel de l'OQT belge, l'une EXACTEMENT de ces 4 valeurs (null sinon) : "SEJOUR_IRREGULIER_ART_7" (séjour irrégulier art. 7 al.1 1° — absence de titre ou titre expiré), "REFUS_SEJOUR_APRES_DEMANDE" (refus de séjour notifié après une demande — annexe 13 suite à décision négative sur demande introduite), "FIN_SEJOUR_REGULIER" (fin de séjour régulier — expiration d'un titre non renouvelé, annexe 15 terminée, rejet asile sans autre titre), "AUTRE" (motif non couvert par les 3 premiers — à utiliser avec parcimonie, uniquement si clairement un motif distinct). Ne jamais inventer ; si le motif exact n'est pas identifiable dans les pièces, utiliser null. Dossiers FR : null.
            "transfert_imminent_detected" : booléen — true SEULEMENT s'il y a des indices factuels clairs d'un transfert imminent vers un centre fermé ou la frontière (placement en centre fermé notifié, escorte annoncée par l'OE, vol de retour programmé mentionné). false si une mention explicite indique l'absence de placement. null par défaut si non déterminable — c'est le cas attendu pour la plupart des dossiers. Dossiers FR : null.
            F-201 — 9 flags décisionnels niveau 3, FRANCE UNIQUEMENT. Chaque flag est un booléen avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces. Pour un dossier immigration BELGIQUE, TOUS ces 9 flags DOIVENT rester false (les régimes BE équivalents sont gérés par les 5 flags BE ci-dessous). Permettent à F-IA-04 de basculer 10 outils Immigration FR ALWAYS_ON → CONTEXTUAL.
            "aes_metiers_tension_eligible_detecte" : booléen — true si le dossier évoque une admission exceptionnelle au séjour (AES) au titre des métiers en tension (art. L. 435-4 CESEDA, métier figurant à la liste arrêtée par le ministre du Travail) avec indice factuel (fiche de paie sur métier en tension, attestation employeur, mention explicite dans une pièce préfecture / avocat). False par défaut.
            "aes_familial_eligible_detecte" : booléen — true si le dossier évoque une AES au titre des liens personnels et familiaux (art. L. 435-1 CESEDA — durée de séjour, intensité des liens, scolarisation des enfants en France, conjoint Français, etc.). False par défaut.
            "aes_humanitaire_eligible_detecte" : booléen — true si le dossier évoque une AES pour motif humanitaire (art. L. 435-1 CESEDA — situation médicale grave non couverte par L.425-9, victime d'une infraction grave, etc.). False par défaut.
            "aes_etudiant_eligible_detecte" : booléen — true si le dossier évoque une AES au titre étudiant (art. L. 435-3 CESEDA — étudiant en cours d'études, parcours universitaire continu, etc.). False par défaut.
            "changement_statut_envisage_detecte" : booléen — true si le dossier évoque un changement de statut envisagé (étudiant → salarié L.412-1, conjoint → indépendant, asile rejeté → AES, etc.) avec indice factuel (CDI signé, demande déposée, etc.). False par défaut.
            "procedure_asile_detectee" : booléen — true uniquement si le dossier comporte une procédure d'asile en cours ou récente (récépissé asile, dépôt OFPRA, recours CNDA, attestation demande asile, document Dublin). False par défaut.
            "naturalisation_envisagee_detectee" : booléen — true uniquement si le dossier évoque une démarche de naturalisation en cours ou imminente (dossier déposé en préfecture, demande par décret art. 21-15 CCiv, demande par déclaration art. 21-2 / 21-13). False par défaut.
            "client_mineur_detecte" : booléen — true uniquement si le client de l'avocat (ressortissant étranger concerné par le dossier) est mineur au moment de la procédure (date de naissance attestée, mention "MNA", "mineur isolé", "ASE", autorité parentale identifiée). False si majeur. False par défaut.
            "mesure_eloignement_detectee" : booléen — true uniquement si le dossier comporte une mesure d'éloignement notifiée (OQTF L.614-5 ou L.731-1, ITF, expulsion L.631-1+, IRTF). Cumul avec les flags OQTF FR détaillés ci-dessus possible. False par défaut.
            F-203 — 5 flags décisionnels niveau 3, BELGIQUE UNIQUEMENT. Chaque flag est un booléen avec valeur par défaut false ; ne mettre true QUE si un indice factuel concret est documenté dans les pièces. Pour un dossier immigration FRANCE, TOUS ces 5 flags DOIVENT rester false. Permettent à F-IA-04 de basculer 5 outils Immigration BE ALWAYS_ON → CONTEXTUAL.
            "procedure_9bis_envisagee" : booléen — true uniquement si le dossier évoque une procédure de régularisation par circonstances exceptionnelles humanitaires au sens de l'art. 9bis Loi du 15/12/1980 (demande adressée au bourgmestre, motivation humanitaire / liens durables / scolarisation enfants, attente décision Office des étrangers). False par défaut.
            "procedure_9ter_medicale_detectee" : booléen — true uniquement si le dossier évoque une procédure médicale au sens de l'art. 9ter Loi du 15/12/1980 (certificat médical type, maladie grave, absence de traitement disponible au pays d'origine, avis du médecin de l'OE). False par défaut.
            "regroupement_40bis_detecte" : booléen — true uniquement si le dossier évoque un regroupement familial de citoyen UE / EEE / Suisse au sens de l'art. 40bis Loi du 15/12/1980 (conjoint, partenaire enregistré, descendant, ascendant à charge d'un citoyen UE résidant en Belgique). False par défaut.
            "regroupement_40ter_detecte" : booléen — true uniquement si le dossier évoque un regroupement familial de ressortissant tiers ou Belge au sens de l'art. 40ter Loi du 15/12/1980 (conjoint d'un Belge, descendant d'un Belge, ascendant à charge d'un Belge ou d'un ressortissant tiers titulaire d'un titre de long séjour). False par défaut.
            "oqt_annexe13_detectee" : booléen — true uniquement si une annexe 13 / OQT belge a été notifiée au client (art. 7, 74/14 Loi du 15/12/1980 — décision administrative de l'Office des étrangers ordonnant de quitter le territoire). Recoupe en partie "date_notification_annexe13" mais signale la simple présence factuelle même si la date n'est pas extractible. False par défaut.
            "trigger_events" : tableau (éventuellement vide) des événements factuels identifiés dans les pièces qui ouvrent un nouveau droit de séjour (F-150). Chaque élément : {"event_code" : l'un des 10 codes exacts (null si l'événement détecté ne correspond à aucun de ces codes) : "MARIAGE_RESSORTISSANT_FR" (mariage avec Français), "PACS_RESSORTISSANT_FR" (PACS avec Français, communauté de vie > 1 an), "NAISSANCE_ENFANT_FR" (naissance enfant français), "DOCTORAT_OBTENU" (doctorat obtenu en France), "CDI_OBTENU_SALARIE" (CDI signé), "ENTREE_LEGALE_10ANS" (10 ans de titre régulier), "VIOLENCES_CONJUGALES_CONSTATEES" (conjoint victime), "DEMANDE_ASILE_ACCORDEE_OFPRA" (réfugié OFPRA/CNDA), "ENFANT_NE_FR_13ANS_PRESENCE" (né FR + résidence depuis 13 ans), "REGROUPEMENT_FAMILIAL_AUTORISE" ; "event_date" : date factuelle de l'événement YYYY-MM-DD (celle du mariage / doctorat / CDI, pas d'une date de raisonnement), null si inconnue ; "source_document" : nom du document support (ex. "acte_mariage.pdf"), null si non identifiable ; "justification" : phrase courte expliquant l'indice factuel (ex. "Mariage célébré le 15/03/2025 mentionné dans l'acte n°127 de la Mairie du 5ème")}. N'inventer AUCUN événement non directement mentionné dans les pièces. Inclure aussi les événements imminents documentés : soutenance de thèse programmée avec convention d'accueil ; mariage publié des bans ; CDI signé même non commencé ; naissance déclarée et reconnaissance de paternité française. La preuve documentaire (date + acte/attestation officielle) suffit, l'événement n'a pas besoin d'être révolu. Tableau vide [] si aucun événement déclencheur détecté.
            "strategy_scenarios" : tableau (2 à 3 éléments OU vide) de scenarii stratégiques alternatifs quand plusieurs voies juridiques sont ouvertes (F-151). Chaque élément : {"scenario_label" : titre court (ex. "Changement de statut immédiat", "Attendre expiration du titre étudiant") ; "scenario_description" : explication factuelle 1-2 phrases ; "base_legale" : texte CESEDA applicable (ex. "Art. L.423-1 CESEDA") ; "target_title_code" : code titre cible ou null ; "target_title_label" : libellé du titre cible ou alternative en texte libre ; "delay_days_estimate" : fourchette de délai de traitement en jours (ex. "90-180"), null si inconnue ; "risk_level" : "FAIBLE" / "MOYEN" / "ELEVE" (risque d'échec) ; "risk_justification" : phrase courte expliquant le niveau de risque ; "required_additional_pieces" : liste de pièces à ajouter au dossier ; "advantages" : liste de points forts de ce scénario ; "drawbacks" : liste d'inconvénients}. Ne produire un tableau que si la situation offre GENUINEMENT plusieurs voies — sinon tableau vide. 2 ou 3 scenarii maximum, contrastés, pas 2 variantes quasi-identiques.
            SF-246-16 — champs identité requérant + décision contestée pour pré-fill de l'outil générateur de recours F-IM-06. Tous nullables si non lisibles dans les pièces.
            "nom_requerant" : nom de famille du requérant (personne faisant l'objet de la procédure immigration) tel qu'il apparaît dans les pièces (passeport, titre de séjour, décision préfectorale), en texte libre. Null si non identifiable avec certitude.
            "prenom_requerant" : prénom du requérant tel qu'il apparaît dans les pièces, en texte libre. Null si non identifiable avec certitude.
            "date_decision_contestee" : date de la décision administrative contestée par le recours (refus de renouvellement, décision OFPRA, refus préfectoral, etc.) au format YYYY-MM-DD. Null si non déterminable. À ne pas confondre avec "date_notification_decision_contestee" (date de notification postale) — ici la date de la décision elle-même si distincte et lisible, sinon utiliser "date_notification_decision_contestee" comme fallback.
            "reference_decision" : numéro ou référence de la décision contestée tel qu'il figure dans l'acte administratif (ex. "n°2024-PRF-75-001234", "SIPSI 2024-00567"). Null si non présent dans les pièces.
            SF-246-17 — champs pré-fill outils dublin-recours (F-IM-22) et crrv-refus-visa (F-IM-23). FRANCE UNIQUEMENT — null pour tout dossier belge. Tous nullables si non lisibles dans les pièces.
            "dublin_etat_membre_responsable" : État membre de l'Union européenne désigné comme responsable de la demande d'asile en application du Règlement Dublin III (Règl. UE 604/2013, art. 3). Indiquer le nom de l'État en texte libre tel qu'il apparaît dans la décision de transfert (ex. "Allemagne", "Italie", "Espagne"). Null si aucune décision de transfert Dublin n'est identifiable dans les pièces ou si le dossier n'est pas un dossier Dublin. Dossier belge : null.
            "dublin_motif_transfert" : motif juridique du transfert Dublin — CLASSER OBLIGATOIREMENT dans l'une de ces 5 valeurs EXACTES : "DEMANDE_ASILE_AUTRE_ETAT" (demande d'asile antérieure dans un autre État membre, art. 13 Règl. 604/2013), "VISA_DELIVRE_AUTRE_ETAT" (visa délivré par un autre État membre, art. 12), "ENTREE_IRREGULIERE_AUTRE_ETAT" (entrée irrégulière par un autre État membre, art. 13 al. 1), "MEMBRE_FAMILLE_AUTRE_ETAT" (membre de famille dans un autre État membre, art. 8-11), "AUTRE" (autre motif Dublin identifiable mais non couvert par les 4 catégories). "AUTRE" n'est PAS une valeur de doute : utiliser UNIQUEMENT si le motif Dublin est identifié mais ne rentre dans aucune des 4 catégories. Si le motif Dublin n'est pas identifiable avec certitude, laisser null. Null pour tout dossier non-Dublin ou belge.
            "crrv_type_visa" : type de visa refusé faisant l'objet du recours CRRV (Commission de recours contre les refus de visa, CESEDA L.312-1 à L.312-3) — CLASSER dans l'une de ces 5 valeurs EXACTES : "COURT_SEJOUR" (visa Schengen court séjour ≤ 90 j, art. L.312-1), "LONG_SEJOUR" (visa national long séjour > 3 mois, D.312-3), "REGROUPEMENT_FAMILIAL" (visa regroupement familial, art. R.211-19+), "ETUDIANT" (visa étudiant D ≥ 3 mois), "AUTRE" (autre type de visa identifié mais non couvert). "AUTRE" n'est PAS une valeur de doute : utiliser null si le type de visa n'est pas identifiable avec certitude dans la décision de refus. Null pour tout dossier non-CRRV ou belge.
            "crrv_motif_refus" : motif du refus de visa tel qu'il est formulé dans la décision de refus CRRV, en texte libre (≤ 500 caractères). Citer le motif exact ou résumer fidèlement la motivation administrative (ex. "Ressources insuffisantes pour la durée du séjour", "Intention de retour non établie", "Documents manquants"). Null si aucune décision de refus de visa n'est présente dans les pièces ou si le motif n'est pas lisible. Dossier belge : null.
            SF-246-18 — 7 champs IA FRANCE UNIQUEMENT pour pré-fill des outils AES (aes-etudiant L.435-3, aes-famille L.435-1, aes-humanitaire L.435-2, aes-metiers-tension L.435-4). Tous ces champs DOIVENT rester null pour un dossier immigration BELGIQUE. Le bar est : TENTER l'extraction dès qu'un indice documentaire existe ; null uniquement si l'information est ABSENTE des pièces — ne pas mettre null pour "doute" si la valeur est lisible.
            "aes_date_entree_france" : date d'entrée en France du requérant au format YYYY-MM-DD, telle qu'elle figure sur le passeport (tampon / visa d'entrée) ou sur un premier titre de séjour. Ne JAMAIS renvoyer une date future. Ne JAMAIS confondre avec "date_depot_procedure" (date de dépôt de la demande). Null si non détectable dans les pièces ou dossier belge.
            "aes_annees_scolarite_consecutives" : nombre ENTIER d'années d'études consécutives effectuées en France, extrait des certificats de scolarité ou attestations universitaires présentés au dossier. Doit refléter la continuité : si une interruption scolaire est mentionnée, ne compter que la période la plus récente ininterrompue. Entier ≥ 0. Null si non déterminable ou dossier belge.
            "aes_niveau_etudes" : niveau d'études le plus élevé mentionné dans les pièces, CLASSER dans l'une de ces 4 valeurs EXACTES : "LYCEE" (niveau lycée / secondaire, bac non obtenu ou bac en cours), "BAC_PLUS_1_2" (bac obtenu + 1 ou 2 ans d'études supérieures : BTS, DUT, L1, L2), "BAC_PLUS_3_4" (licence L3 / bachelor, Master 1 M1), "BAC_PLUS_5_PLUS" (Master 2 M2, Doctorat, Grande école). Si ambigu, utiliser le niveau inférieur plutôt que supérieur. Null si non déterminable ou dossier belge.
            "aes_duree_scolarite_plus_ancien_enfant_annees" : pour les dossiers familiaux (aes-famille), durée en ANNÉES ENTIÈRES de scolarité en France de l'enfant inscrit depuis le plus longtemps (l'enfant "plus ancien"), telle qu'elle ressort des attestations de scolarité. Si plusieurs enfants sont présents, prendre celui scolarisé depuis le plus longtemps. Entier ≥ 0. Null si aucun enfant scolarisé n'est mentionné ou dossier belge.
            "aes_motif_humanitaire" : pour les dossiers humanitaires (aes-humanitaire), motif humanitaire dominant tel qu'il est factuel dans les pièces, CLASSER dans l'une de ces 6 valeurs EXACTES : "RISQUES_AU_RETOUR" (risques personnels sérieux — persécution, conflits, discrimination grave — en cas de retour au pays), "ISOLEMENT_TOTAL" (absence totale de liens familiaux au pays d'origine, isolement complet documenté), "VICTIME_VIOLENCES" (victime de violences conjugales, intrafamiliales ou sexuelles documentées en France), "VICTIME_TRAITE" (victime de traite d'êtres humains ou de proxénétisme), "SITUATION_MEDICALE_PRECAIRE_HORS_L425_9" (état de santé grave nécessitant des soins non disponibles ou inaccessibles au pays d'origine, mais HORS périmètre L.425-9 maladie grave), "AUTRE_HUMANITAIRE" (tout autre motif humanitaire identifié et documenté qui ne rentre dans aucune des 5 catégories précédentes). Null si aucun motif humanitaire factuel identifiable ou dossier belge.
            "aes_mois_activite_salariee" : pour les dossiers "métiers en tension" (aes-metiers-tension), nombre ENTIER de mois de travail salarié dans les 24 DERNIERS MOIS, tel qu'il ressort des bulletins de paie, contrats de travail ou attestations employeur. Compter les mois où une activité salariée est attestée, même discontinue. Entier de 0 à 24 (ne jamais dépasser 24 — borner si nécessaire). Null si non déterminable ou dossier belge.
            "aes_code_metier" : pour les dossiers "métiers en tension" (aes-metiers-tension), code ROME exact (ex. "N1101", "K1304") ou libellé du métier exercé tel qu'il figure sur l'attestation employeur ou la fiche de paie (ex. "Infirmier(ère)", "Cuisinier", "Maçon"). Null si non déterminable ou dossier belge.
            """;

    private LegalDomainPromptBuilder() {}

    /**
     * Construit la description du domaine juridique selon le domaine et le pays.
     * Ex : "droit du travail français", "droit de l'immigration belge"
     */
    public static String domainLabel(String legalDomain, String country) {
        String domainPart = switch (legalDomain) {
            case "DROIT_IMMIGRATION" -> "droit de l'immigration";
            case "DROIT_FAMILLE"     -> "droit de la famille";
            default                  -> "droit du travail"; // DROIT_DU_TRAVAIL
        };

        boolean isFeminine = "DROIT_IMMIGRATION".equals(legalDomain);
        String countryAdjective = switch (country) {
            case "BELGIQUE" -> isFeminine ? "belge" : "belge";
            default         -> isFeminine ? "française" : "français"; // FRANCE
        };

        return domainPart + " " + countryAdjective;
    }

    public static String domainSpecificInstruction(String legalDomain) {
        if ("DROIT_DU_TRAVAIL".equals(legalDomain)) return TRAVAIL_INSTRUCTION;
        if ("DROIT_IMMIGRATION".equals(legalDomain)) return IMMIGRATION_INSTRUCTION;
        if ("DROIT_FAMILLE".equals(legalDomain))     return FAMILLE_INSTRUCTION;
        return "";
    }
}
